        )}
      </div>
    </div>
  );
};

// --- Main Portfolio Component ---
export const Portfolio: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState(ALL_CATEGORY);
  const [activeTag, setActiveTag] = useState(ALL_TAG);
  const [selectedProjectState, setSelectedProjectState] = useState<{ project: Project; autoPlay: boolean } | null>(null);
  const [visibleCount, setVisibleCount] = useState(6);
  const [isVisible, setIsVisible] = useState(false);
  const [isFilterAnimating, setIsFilterAnimating] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) observer.disconnect();
    };
  }, []);

  const handleCategoryChange = (cat: string) => {
    if (activeCategory === cat) return;
    setIsFilterAnimating(true);
    setTimeout(() => {
      setActiveCategory(cat);
      setVisibleCount(6);
      requestAnimationFrame(() => {
        setIsFilterAnimating(false);
      });
    }, 300);
  };

  const handleTagChange = (tag: string) => {
    if (activeTag === tag) return;
    setIsFilterAnimating(true);
    setTimeout(() => {
      setActiveTag(tag);
      setVisibleCount(6);
      requestAnimationFrame(() => {
        setIsFilterAnimating(false);
      });
    }, 300);
  };

  const categories = [ALL_CATEGORY, ...Array.from(new Set(PROJECTS.map(p => p.category)))];
  const allTags = [ALL_TAG, ...Array.from(new Set(PROJECTS.flatMap(p => p.technologies || []))).sort()];

  const getCategoryCount = (cat: string) => {
     return PROJECTS.filter(p => {
       const matchCat = cat === ALL_CATEGORY || p.category === cat;
       const matchTag = activeTag === ALL_TAG || (p.technologies && p.technologies.includes(activeTag));
       return matchCat && matchTag;
     }).length;
  };

  const getTagCount = (tag: string) => {
    return PROJECTS.filter(p => {
       const matchCat = activeCategory === ALL_CATEGORY || p.category === activeCategory;
       const matchTag = tag === ALL_TAG || (p.technologies && p.technologies.includes(tag));
       return matchCat && matchTag;
    }).length;
  };

  const filteredProjects = PROJECTS.filter(p => {
    return (activeCategory === ALL_CATEGORY || p.category === activeCategory) && 
           (activeTag === ALL_TAG || (p.technologies && p.technologies.includes(activeTag)));
  });

  const displayedProjects = filteredProjects.slice(0, visibleCount);

  return (
    <section ref={sectionRef} id={SectionId.PORTFOLIO} className="py-24 pt-32 bg-slate-50 dark:bg-slate-950 min-h-screen">
      <div className="container mx-auto px-6">
        <div className={`text-center max-w-3xl mx-auto mb-12 transition-all duration-700 ease-out transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`}>
          <h2 className="text-sm font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-3">Our Work</h2>
          <h3 className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white leading-tight mb-4">
            Showcasing our success stories.
          </h3>
          <p className="text-slate-600 dark:text-slate-400 text-lg">
            From concept to launch, we've helped businesses across the globe achieve their digital goals.
          </p>
        </div>

        <div className={`flex flex-wrap justify-center gap-3 mb-8 transition-all duration-700 delay-100 ease-out transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`} role="tablist" aria-label="Filter projects by category">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => handleCategoryChange(cat)}
              role="tab"
              aria-selected={activeCategory === cat}
              className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-300 transform active:scale-95 flex items-center gap-2 ${
                activeCategory === cat
                  ? 'bg-slate-900 text-white shadow-lg ring-2 ring-slate-900 ring-offset-2 ring-offset-slate-50 dark:ring-offset-slate-900 scale-105'
                  : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800'
              }`}
            >
              {cat} 
              <span className={`text-xs font-bold px-1.5 py-0.5 rounded-full transition-colors duration-300 ml-1 ${
                activeCategory === cat ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-500'
              }`}>
                {getCategoryCount(cat)}
              </span>
            </button>
          ))}
        </div>

        <div className={`flex items-center justify-center gap-2 mb-12 overflow-x-auto no-scrollbar py-2 px-4 max-w-5xl mx-auto transition-all duration-700 delay-200 ease-out transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`}>
          <div className="flex items-center gap-2 bg-white/50 dark:bg-slate-900/50 p-2 rounded-full border border-slate-200 dark:border-slate-800 backdrop-blur-sm">
             <Tag size={16} className="text-slate-400 ml-2" aria-hidden="true" />
             {allTags.map((tag) => (
              <button
                key={tag}
                onClick={() => handleTagChange(tag)}
                aria-pressed={activeTag === tag}
                className={`px-3 py-1 rounded-full text-xs font-semibold transition-all duration-200 active:scale-95 whitespace-nowrap flex items-center gap-1 ${
                  activeTag === tag
                    ? 'bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300 shadow-sm'
                    : 'bg-transparent text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-800'
                }`}
              >
                {tag} 
                <span className="text-[10px] opacity-70 ml-1">{getTagCount(tag)}</span>
              </button>
            ))}
          </div>
        </div>

        <div className={`transition-all duration-500 ease-in-out ${isFilterAnimating ? 'opacity-0 scale-[0.98]' : 'opacity-100 scale-100'}`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 min-h-[400px]">
            {displayedProjects.map((project, index) => (
              <ProjectCard 
                key={project.id} 
                index={index}
                project={project} 
                onClick={() => setSelectedProjectState({ project, autoPlay: false })} 
                onViewDemo={() => setSelectedProjectState({ project, autoPlay: true })}
              />
            ))}
            {displayedProjects.length === 0 && (
              <div className="col-span-full flex flex-col items-center justify-center text-slate-400 py-12">
                 <Code2 className="w-12 h-12 text-slate-300 mb-4" aria-hidden="true" />
                 <p className="font-medium">No projects found matching your criteria.</p>
                 <button onClick={() => { handleCategoryChange(ALL_CATEGORY); handleTagChange(ALL_TAG); }} className="mt-4 text-blue-500 text-sm hover:underline">Clear all filters</button>
              </div>
            )}
          </div>
        </div>

        {visibleCount < filteredProjects.length && (
          <div className="mt-16 text-center">
            <Button variant="outline" onClick={() => setVisibleCount(p => p + 3)} className="group px-8">
              View More Projects <ArrowDown className="ml-2 w-4 h-4 transition-transform group-hover:translate-y-1" aria-hidden="true" />
            </Button>
          </div>
        )}
      </div>

      <ProjectModal 
        project={selectedProjectState?.project || null} 
        autoPlay={selectedProjectState?.autoPlay}
        onClose={() => setSelectedProjectState(null)} 
        onProjectSelect={(p) => setSelectedProjectState({ project: p, autoPlay: false })} 
      />
    </section>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Mail, MapPin, Phone, Send, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Button } from './ui/Button';
import { ADDRESS, CONTACT_EMAIL } from '../constants';
import { SectionId } from '../types';

export const Contact: React.FC = () => {
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [errors, setErrors] = useState<{ name?: string; email?: string; message?: string }>({});
  const [status, setStatus] = useState<'idle' | 'sending' | 'success'>('idle');
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  const validate = () => {
    const newErrors: typeof errors = {};
    if (!formData.name.trim()) newErrors.name = 'Name is required';
    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }
    if (!formData.message.trim()) newErrors.message = 'Message is required';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setStatus('sending');
    setTimeout(() => {
      setStatus('success');
      setFormData({ name: '', email: '', message: '' });
      setErrors({});
      setTimeout(() => setStatus('idle'), 5000);
    }, 1500);
  };

  return (
    <section ref={sectionRef} id={SectionId.CONTACT} className="py-24 bg-slate-900 text-white overflow-hidden">
      <div className="container mx-auto px-6">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">

          <div className="space-y-8">
            <div className={`transition-all duration-1000 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-6'}`}>
              <h2 className="text-sm font-bold text-blue-400 uppercase tracking-widest mb-3">Get in Touch</h2>
              <h3 className="text-3xl md:text-5xl font-bold leading-tight">
                Let's build something <br/> <span className="text-blue-500">extraordinary</span> together.
              </h3>
            </div>

            <p className={`text-slate-300 text-lg max-w-md transition-all duration-1000 delay-100 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-6'}`}>
              Have a project in mind? We'd love to hear from you. Send us a message and we'll get back to you within 24 hours.
            </p>

            <div className="space-y-6 pt-8">
              {[
                { icon: Mail, label: 'Email Us', value: CONTACT_EMAIL },
                { icon: MapPin, label: 'Visit Us', value: ADDRESS },
                { icon: Phone, label: 'Call Us', value: '+880 1234 567890' }
              ].map((item, idx) => (
                <div key={item.label} className={`flex items-start gap-4 transition-all duration-700 ease-out ${isVisible ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-6'}`} style={{ transitionDelay: `${200 + (idx * 150)}ms` }}>
                  <div className="p-3 bg-slate-800 rounded-lg border border-slate-700" aria-hidden="true">
                    <item.icon className="w-6 h-6 text-blue-400" />
                  </div>
                  <div>
                    <p className="text-sm text-slate-400 mb-1">{item.label}</p>
                    <p className="text-lg font-medium text-slate-100">{item.value}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className={`bg-slate-800/50 p-8 md:p-10 rounded-3xl border border-slate-700 transition-all duration-1000 delay-300 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-6'}`}>
             {status === 'success' ? (
                <div className="h-full flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-500 py-12">
                   <div className="w-20 h-20 bg-blue-500/20 rounded-full flex items-center justify-center text-blue-400 mb-6">
                      <CheckCircle2 size={40} />
                   </div>
                   <h4 className="text-2xl font-bold mb-2">Message Sent!</h4>
                   <p className="text-slate-400 mb-8">Thank you for reaching out. We'll be in touch very soon.</p>
                   <Button variant="outline" onClick={() => setStatus('idle')} className="text-white border-slate-700 hover:bg-slate-700">Send another message</Button>
                </div>
             ) : (
               <form onSubmit={handleSubmit} className="space-y-6" noValidate>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="group relative">
                     <label htmlFor="name" className={`block text-xs font-bold uppercase text-blue-400 mb-1 tracking-wide transition-all ${formData.name ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-1'}`}>
                        Name
                     </label>
                     <input 
                        type="text" 
                        id="name"
                        aria-invalid={!!errors.name}
                        aria-describedby={errors.name ? "name-error" : undefined}
                        className={`w-full bg-slate-900 border ${errors.name ? 'border-red-500' : 'border-slate-700'} rounded-lg px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-blue-500 transition-all duration-300`}
                        placeholder="Full Name"
                        value={formData.name}
                        onChange={(e) => {
                          setFormData({...formData, name: e.target.value});
                          if(errors.name) setErrors({...errors, name: undefined});
                        }}
                     />
                     {errors.name && <p id="name-error" className="text-red-400 text-xs mt-1 flex items-center gap-1 animate-in slide-in-from-top-1"><AlertCircle size={12} /> {errors.name}</p>}
                   </div>

                   <div className="group relative">
                     <label htmlFor="email" className={`block text-xs font-bold uppercase text-blue-400 mb-1 tracking-wide transition-all ${formData.email ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-1'}`}>
                        Email
                     </label>
                     <input 
                        type="email" 
                        id="email"
                        aria-invalid={!!errors.email}
                        aria-describedby={errors.email ? "email-error" : undefined}
                        className={`w-full bg-slate-900 border ${errors.email ? 'border-red-500' : 'border-slate-700'} rounded-lg px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-blue-500 transition-all duration-300`}
                        placeholder="Email Address"
                        value={formData.email}
                        onChange={(e) => {
                          setFormData({...formData, email: e.target.value});
                          if(errors.email) setErrors({...errors, email: undefined});
                        }}
                     />
                     {errors.email && <p id="email-error" className="text-red-400 text-xs mt-1 flex items-center gap-1 animate-in slide-in-from-top-1"><AlertCircle size={12} /> {errors.email}</p>}
                   </div>
                 </div>

                 <div className="group relative">
                   <label htmlFor="message" className={`block text-xs font-bold uppercase text-blue-400 mb-1 tracking-wide transition-all ${formData.message ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-1'}`}>
                      Message
                   </label>
                   <textarea 
                      id="message"
                      aria-invalid={!!errors.message}
                      aria-describedby={errors.message ? "message-error" : undefined}
                      rows={4}
                      className={`w-full bg-slate-900 border ${errors.message ? 'border-red-500' : 'border-slate-700'} rounded-lg px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-blue-500 transition-all duration-300 resize-none`}
                      placeholder="Tell us about your project requirements..."
                      value={formData.message}
                      onChange={(e) => {
                        setFormData({...formData, message: e.target.value});
                        if(errors.message) setErrors({...errors, message: undefined});
                      }}
                   />
                   {errors.message && <p id="message-error" className="text-red-400 text-xs mt-1 flex items-center gap-1 animate-in slide-in-from-top-1"><AlertCircle size={12} /> {errors.message}</p>}
                 </div>

                 <Button 
                   type="submit" 
                   variant="primary" 
                   size="lg" 
                   className="w-full bg-blue-600 hover:bg-blue-700 shadow-xl shadow-blue-900/40 active:scale-95 transition-all"
                   disabled={status === 'sending'}
                   aria-label={status === 'sending' ? 'Sending message' : 'Send message now'}
                 >
                   {status === 'sending' ? (
                      <span className="flex items-center gap-2">
                        <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                        Sending...
                      </span>
                   ) : (
                     <span className="flex items-center">
                       Send Message <Send className="ml-2 w-4 h-4" aria-hidden="true" />
                     </span>
                   )}
                 </Button>
               </form>
             )}
          </div>
        </div>
      </div>
    </section>
  );
};

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
