                className={`px-7 py-3 rounded-full text-sm font-bold transition-all transform hover:scale-105 active:scale-95 border ${activeCategory === c ? 'bg-blue-600 border-blue-600 text-white shadow-xl shadow-blue-500/30 animate-pulse-subtle' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 border-slate-200 dark:border-slate-700 hover:border-blue-400 dark:hover:border-blue-600'}`}
              >
                {c}
              </button>
            ))}
          </div>

          <div className="flex flex-wrap justify-center gap-2 overflow-x-auto no-scrollbar pb-6 max-w-5xl mx-auto">
            {tags.map(t => (
              <button 
                key={t} 
