                className="p-3 rounded-2xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 disabled:opacity-30 transition-all hover:bg-slate-100 dark:hover:bg-slate-700 shadow-sm"
                aria-label="Previous Page"
              >
                <ChevronLeft size={22} />
              </button>
              <div className="flex items-center gap-3">
                {Array.from({ length: totalPages }).map((_, i) => (
                  <button
                    key={i}
                    onClick={() => { setCurrentPage(i + 1); document.getElementById(SectionId.PORTFOLIO)?.scrollIntoView({ behavior: 'smooth' }); }}
                    className={`w-12 h-12 rounded-2xl text-base font-bold transition-all transform active:scale-90 ${currentPage === i + 1 ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/20' : 'bg-white dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 border border-slate-200 dark:border-slate-700'}`}
                  >
                    {i + 1}
                  </button>
                ))}
              </div>
              <button 
                onClick={() => { setCurrentPage(p => Math.min(totalPages, p + 1)); document.getElementById(SectionId.PORTFOLIO)?.scrollIntoView({ behavior: 'smooth' }); }}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 disabled:opacity-30 transition-all hover:bg-slate-100 dark:hover:bg-slate-700 shadow-sm"
