                        placeholder="John Doe" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} 
                      />
                     {errors.name && <p className="text-red-500 text-xs mt-1.5 flex items-center gap-1.5 font-bold animate-in slide-in-from-top-1"><AlertCircle size={14} /> {errors.name}</p>}
                   </div>
                   <div className="space-y-2">
                     <label htmlFor="email" className="text-xs font-bold uppercase text-slate-400 ml-1">Work Email</label>
                     <input 
                        type="email" id="email" aria-invalid={!!errors.email} 
                        className={`w-full bg-slate-50 dark:bg-slate-800/50 border-2 ${errors.email ? 'border-red-500' : 'border-slate-200 dark:border-slate-700'} rounded-2xl px-5 py-4 text-slate-900 dark:text-white focus:outline-none focus:border-blue-600 dark:focus:border-blue-500 transition-all font-medium placeholder:text-slate-300 dark:placeholder:text-slate-600`} 
                        placeholder="john@company.com" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} 
                      />
                     {errors.email && <p className="text-red-500 text-xs mt-1.5 flex items-center gap-1.5 font-bold animate-in slide-in-from-top-1"><AlertCircle size={14} /> {errors.email}</p>}
                   </div>
                 </div>

                 <div className="space-y-2">
                   <label htmlFor="message" className="text-xs font-bold uppercase text-slate-400 ml-1">How can we help?</label>
                   <textarea 
                      id="message" aria-invalid={!!errors.message} rows={5} 
                      className={`w-full bg-slate-50 dark:bg-slate-800/50 border-2 ${errors.message ? 'border-red-500' : 'border-slate-200 dark:border-slate-700'} rounded-2xl px-5 py-4 text-slate-900 dark:text-white focus:outline-none focus:border-blue-600 dark:focus:border-blue-500 transition-all resize-none font-medium placeholder:text-slate-300 dark:placeholder:text-slate-600`} 
                      placeholder="Tell us about your project or goals..." value={formData.message} onChange={(e) => setFormData({...formData, message: e.target.value})} 
                    />
                   {errors.message && <p className="text-red-500 text-xs mt-1.5 flex items-center gap-1.5 font-bold animate-in slide-in-from-top-1"><AlertCircle size={14} /> {errors.message}</p>}
                 </div>

                 <Button 
                   type="submit" variant="primary" size="lg" 
                   className="w-full bg-blue-600 hover:bg-blue-700 text-white rounded-2xl shadow-xl shadow-blue-500/30 transform active:scale-[0.98] transition-all font-bold text-lg h-16" 
                   disabled={status === 'sending'}
                 >
                   {status === 'sending' ? (
                     <div className="flex items-center gap-3">
                       <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div> 
                       Processing...
                     </div>
                   ) : <span className="flex items-center gap-2">Send Message <Send size={20} className="transform -rotate-12" /></span>}
                 </Button>
               </form>
             )}
          </div>
        </div>
      </div>
    </section>
  );
};

