// --- Project Card Component ---
const ProjectCard: React.FC<{ 
  project: Project; 
  index: number; 
  onSelect: (p: Project, mode: 'full' | 'quick' | 'video') => void; 
  onTagClick: (tag: string) => void 
}> = ({ project, index, onSelect, onTagClick }) => {
  const [isVisible, setIsVisible] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const obs = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { setIsVisible(true); obs.disconnect(); } }, { threshold: 0.1 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  const getStatusColor = (status: string | undefined) => {
    switch(status) {
      case 'Completed': return 'bg-green-500';
      case 'In Progress': return 'bg-blue-500';
      case 'Maintenance': return 'bg-amber-500';
      default: return 'bg-slate-500';
    }
  };

  return (
    <div 
      ref={ref} 
      className={`group bg-white dark:bg-slate-900 rounded-[2.5rem] overflow-hidden border border-slate-100 dark:border-slate-800 shadow-sm transition-all duration-700 ease-out hover:-translate-y-3 hover:shadow-2xl ${isVisible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-12 scale-95'}`}
      style={{ transitionDelay: `${(index % PROJECTS_PER_PAGE) * 80}ms` }}
    >
      <div className="relative aspect-video overflow-hidden cursor-pointer">
        <img src={project.imageUrl} alt={project.title} loading="lazy" className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" />

        {/* Description Overlay on Hover */}
        <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-md opacity-0 group-hover:opacity-100 transition-all duration-500 ease-in-out p-8 flex flex-col justify-center text-white translate-y-4 group-hover:translate-y-0 pointer-events-none group-hover:pointer-events-auto">
          <p className="text-sm line-clamp-4 leading-relaxed font-semibold mb-8 opacity-0 group-hover:opacity-100 transition-all delay-150 duration-500">
            {project.description}
          </p>
          <div className="grid grid-cols-2 gap-3 opacity-0 group-hover:opacity-100 transition-all delay-250 duration-500">
             <button className="px-4 py-3 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all transform active:scale-90 flex items-center justify-center gap-2 shadow-2xl" onClick={(e) => { e.stopPropagation(); onSelect(project, 'full'); }}>
               Case Study <ArrowUpRight size={14} />
             </button>
             <button className="px-4 py-3 bg-slate-800 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-600 transition-all transform active:scale-90 flex items-center justify-center gap-2 shadow-2xl" onClick={(e) => { e.stopPropagation(); onSelect(project, 'quick'); }}>
               Quick View <Eye size={14} />
             </button>
             {project.demoVideoUrl && (
               <button onClick={(e) => { e.stopPropagation(); onSelect(project, 'video'); }} className="col-span-2 px-6 py-3 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 transition-all transform active:scale-90 flex items-center justify-center gap-2 shadow-2xl">
                 <Play size={12} fill="currentColor" /> Play Demo
               </button>
             )}
          </div>
        </div>
      </div>
      <div className="p-8">
        <div className="flex justify-between items-center mb-4">
           <div className="flex items-center gap-2">
             <span className="text-[10px] font-black uppercase tracking-[0.15em] text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 px-3 py-1 rounded-lg">{project.category}</span>
             <div className="flex items-center gap-1.5 ml-2">
               <span className={`w-2 h-2 rounded-full animate-pulse ${getStatusColor(project.status)}`} />
               <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{project.status}</span>
             </div>
           </div>
           <span className="text-[10px] font-black text-slate-400 flex items-center gap-1.5"><Clock size={12} /> {project.duration || 'N/A'}</span>
        </div>
        <h4 className="text-2xl font-black mb-6 tracking-tight group-hover:text-blue-600 transition-colors cursor-pointer" onClick={() => onSelect(project, 'full')}>{project.title}</h4>
        <div className="flex flex-wrap gap-2.5">
          {project.technologies?.slice(0, 4).map(t => (
            <div key={t} className="relative group/tag">
              <button 
                onClick={(e) => { e.stopPropagation(); onTagClick(t); }}
                className="text-[10px] bg-slate-50 dark:bg-slate-800 hover:bg-blue-600 dark:hover:bg-blue-600 text-slate-500 dark:text-slate-400 hover:text-white px-3 py-1.5 rounded-xl transition-all transform hover:scale-110 active:scale-90 font-black border border-slate-100 dark:border-slate-700 hover:border-blue-400"
              >
                {t}
              </button>
              <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 bg-slate-900 dark:bg-slate-800 text-white text-[9px] font-black uppercase tracking-widest rounded-lg opacity-0 group-hover/tag:opacity-100 transition-all pointer-events-none whitespace-nowrap z-30 shadow-2xl border border-white/10 scale-90 group-hover/tag:scale-100">
                View {t} Work
              </span>
            </div>
          ))}
          {project.technologies && project.technologies.length > 4 && (
            <span className="text-[10px] bg-slate-50 dark:bg-slate-800 px-3 py-1.5 rounded-xl text-slate-400 font-black border border-slate-100 dark:border-slate-700">+{project.technologies.length - 4}</span>
          )}
