  );
};

// --- Main Portfolio Component ---
export const Portfolio: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState(() => localStorage.getItem('portfolio_cat') || ALL_CATEGORY);
  const [activeTag, setActiveTag] = useState(() => localStorage.getItem('portfolio_tag') || ALL_TAG);
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedProject, setSelectedProject] = useState<{ project: Project; mode: 'full' | 'quick' | 'video' } | null>(null);
  const [isFilterAnimating, setIsFilterAnimating] = useState(false);

  useEffect(() => {
    localStorage.setItem('portfolio_cat', activeCategory);
    localStorage.setItem('portfolio_tag', activeTag);
  }, [activeCategory, activeTag]);

  const handleSetCategory = (cat: string) => {
    if (activeCategory === cat) return;
    setIsFilterAnimating(true);
    setTimeout(() => {
      setActiveCategory(cat);
      setCurrentPage(1);
      setIsFilterAnimating(false);
    }, 450);
  };

  const handleSetTag = (tag: string) => {
    if (activeTag === tag) return;
    setIsFilterAnimating(true);
    setTimeout(() => {
      setActiveTag(tag);
      setCurrentPage(1);
      setIsFilterAnimating(false);
    }, 450);
  };

  const resetFilters = () => {
    setIsFilterAnimating(true);
    setTimeout(() => {
      setActiveCategory(ALL_CATEGORY);
      setActiveTag(ALL_TAG);
      setCurrentPage(1);
      setIsFilterAnimating(false);
    }, 450);
  };

  const filteredProjects = PROJECTS.filter(p => (activeCategory === ALL_CATEGORY || p.category === activeCategory) && (activeTag === ALL_TAG || p.technologies?.includes(activeTag)));

  const totalPages = Math.ceil(filteredProjects.length / PROJECTS_PER_PAGE);
  const currentProjects = filteredProjects.slice((currentPage - 1) * PROJECTS_PER_PAGE, currentPage * PROJECTS_PER_PAGE);

  const categories = [ALL_CATEGORY, ...Array.from(new Set(PROJECTS.map(p => p.category)))];
  const tags = [ALL_TAG, ...Array.from(new Set(PROJECTS.flatMap(p => p.technologies || []))).sort()];

  return (
    <section id={SectionId.PORTFOLIO} className="py-24 bg-slate-50 dark:bg-slate-950 min-h-[1000px] transition-colors duration-500 overflow-hidden relative">
      <div className="container mx-auto px-6 relative z-10">
        <div className="text-center max-w-4xl mx-auto mb-20">
          <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 text-[10px] font-black uppercase tracking-[0.2em] mb-8">
             <Rocket size={16} /> Showcase Gallery
          </div>
          <h2 className="text-5xl md:text-7xl font-black mb-8 tracking-tighter text-slate-900 dark:text-white">Engineering <br className="hidden md:block"/> Success Stories</h2>
          <p className="text-slate-600 dark:text-slate-400 text-xl font-medium mb-16 max-w-2xl mx-auto">High-performance digital products for global clients, delivered with precision.</p>

          <div className="flex flex-col gap-8 items-center">
            <div className="flex flex-wrap justify-center gap-4">
              {categories.map(c => (
                <button 
                  key={c} 
                  onClick={() => handleSetCategory(c)} 
                  className={`px-10 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all transform hover:scale-105 active:scale-95 border-2 ${activeCategory === c ? 'bg-blue-600 border-blue-600 text-white shadow-2xl shadow-blue-500/40 ring-4 ring-blue-500/10' : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 border-slate-100 dark:border-slate-800 hover:border-blue-300'}`}
                >
                  {c}
                </button>
              ))}
              <button 
                onClick={resetFilters}
                className="px-6 py-4 rounded-2xl bg-white dark:bg-slate-800 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 border-2 border-slate-100 dark:border-slate-800 transition-all transform hover:scale-105 flex items-center gap-2 font-black uppercase text-[11px] tracking-widest shadow-sm"
              >
                <RefreshCw size={14} className={isFilterAnimating ? 'animate-spin' : ''} /> Reset
              </button>
            </div>

            <div className="flex flex-wrap justify-center gap-2 overflow-x-auto no-scrollbar pb-8 max-w-5xl mx-auto px-4">
              {tags.map(t => (
                <button 
                  key={t} 
                  onClick={() => handleSetTag(t)} 
                  className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-[0.15em] transition-all transform hover:scale-110 active:scale-90 border-2 whitespace-nowrap ${activeTag === t ? 'bg-slate-900 border-slate-900 text-white dark:bg-white dark:border-white dark:text-slate-900 shadow-2xl' : 'bg-white dark:bg-slate-900 text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800 border-slate-100 dark:border-slate-800 hover:shadow-lg'}`}
                >
                  {t === ALL_TAG && <Info size={12} className="inline mr-2" />}
                  {t}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className={`transition-all duration-700 transform ${isFilterAnimating ? 'opacity-0 scale-95 translate-y-8 blur-xl' : 'opacity-100 scale-100 translate-y-0 blur-0'}`}>
          {currentProjects.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 mb-20">
              {currentProjects.map((p, i) => (
                <ProjectCard 
                  key={p.id} 
                  project={p} 
                  index={i} 
                  onTagClick={handleSetTag} 
                  onSelect={(p, m) => setSelectedProject({ project: p, mode: m })} 
                />
              ))}
            </div>
          ) : (
            <div className="text-center py-40 bg-white dark:bg-slate-900/50 rounded-[4rem] border-2 border-dashed border-slate-200 dark:border-slate-800 animate-in zoom-in duration-700">
               <SearchX size={80} className="mx-auto text-slate-200 dark:text-slate-800 mb-8" />
               <p className="text-3xl font-black mb-6 text-slate-900 dark:text-white tracking-tight">Zero matches found.</p>
               <p className="text-slate-500 dark:text-slate-400 text-lg mb-12 max-w-md mx-auto">Try clearing your technical filters or exploring our other industry categories.</p>
               <Button onClick={resetFilters} variant="primary" size="lg" className="rounded-2xl px-16 h-16 text-lg font-black">View All Projects</Button>
            </div>
          )}

          {/* Pagination Controls */}
          {totalPages > 1 && (
            <div className="flex items-center justify-center gap-6 mt-20 pt-12 border-t-2 border-slate-100 dark:border-slate-900">
              <button 
                onClick={() => { setCurrentPage(p => Math.max(1, p - 1)); document.getElementById(SectionId.PORTFOLIO)?.scrollIntoView({ behavior: 'smooth' }); }}
                disabled={currentPage === 1}
                className="p-5 rounded-[1.5rem] bg-white dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-800 disabled:opacity-20 transition-all hover:bg-slate-50 dark:hover:bg-slate-800 shadow-xl shadow-slate-200/50 dark:shadow-none focus:outline-none"
                aria-label="Previous Page"
              >
                <ChevronLeft size={28} />
              </button>
              <div className="flex items-center gap-4">
                {Array.from({ length: totalPages }).map((_, i) => (
                  <button
                    key={i}
                    onClick={() => { setCurrentPage(i + 1); document.getElementById(SectionId.PORTFOLIO)?.scrollIntoView({ behavior: 'smooth' }); }}
                    className={`w-14 h-14 rounded-2xl text-lg font-black transition-all transform active:scale-90 border-2 ${currentPage === i + 1 ? 'bg-blue-600 border-blue-600 text-white shadow-2xl shadow-blue-500/30 scale-110' : 'bg-white dark:bg-slate-900 hover:bg-slate-50 dark:hover:bg-slate-800 border-slate-100 dark:border-slate-800 text-slate-400'}`}
                  >
                    {i + 1}
                  </button>
                ))}
              </div>
              <button 
                onClick={() => { setCurrentPage(p => Math.min(totalPages, p + 1)); document.getElementById(SectionId.PORTFOLIO)?.scrollIntoView({ behavior: 'smooth' }); }}
                disabled={currentPage === totalPages}
                className="p-5 rounded-[1.5rem] bg-white dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-800 disabled:opacity-20 transition-all hover:bg-slate-50 dark:hover:bg-slate-800 shadow-xl shadow-slate-200/50 dark:shadow-none focus:outline-none"
                aria-label="Next Page"
              >
                <ChevronRight size={28} />
              </button>
            </div>
          )}
        </div>
      </div>
      <ProjectModal 
        project={selectedProject?.project || null} 
        mode={selectedProject?.mode || 'full'} 
        onClose={() => setSelectedProject(null)} 
      />
    </section>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Mail, MapPin, Send, AlertCircle, CheckCircle2, Copy, Check, Sparkles } from 'lucide-react';
import { Button } from './ui/Button';
import { ADDRESS, CONTACT_EMAIL } from '../constants';
import { SectionId } from '../types';

export const Contact: React.FC = () => {
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [errors, setErrors] = useState<{ name?: string; email?: string; message?: string }>({});
  const [status, setStatus] = useState<'idle' | 'sending' | 'success'>('idle');
  const [isCopied, setIsCopied] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { setIsVisible(true); observer.disconnect(); } }, { threshold: 0.1 });
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const handleCopyEmail = () => {
    navigator.clipboard.writeText(CONTACT_EMAIL);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const validate = () => {
    const newErrors: typeof errors = {};
    if (!formData.name.trim()) newErrors.name = 'Full name is required';
    if (!formData.email.trim()) {
      newErrors.email = 'Email address is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please provide a valid business email';
    }
    if (!formData.message.trim()) newErrors.message = 'Project details are required';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    setStatus('sending');
    // Simulated API call with refined state
    setTimeout(() => {
      setStatus('success');
      setFormData({ name: '', email: '', message: '' });
      setErrors({});
      setTimeout(() => setStatus('idle'), 6000);
    }, 2000);
  };

  return (
    <section ref={sectionRef} id={SectionId.CONTACT} className="py-24 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white transition-colors duration-500 relative overflow-hidden">
      {/* Dynamic Background Design */}
      <div className="absolute top-0 right-0 w-[45%] h-full bg-blue-100/50 dark:bg-blue-900/10 -skew-x-12 transform translate-x-1/4 pointer-events-none transition-colors duration-500" />
      <div className="absolute top-[30%] left-[-5%] w-[400px] h-[400px] bg-indigo-200/40 dark:bg-indigo-900/10 rounded-full blur-[100px] pointer-events-none transition-colors duration-500" />

      <div className="container mx-auto px-6 relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-20 xl:gap-32">
          <div className="space-y-12">
            <div className={`transition-all duration-1000 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
              <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-blue-600/10 dark:bg-blue-400/10 text-blue-700 dark:text-blue-400 text-[11px] font-black uppercase tracking-[0.25em] mb-8 shadow-sm">
                <Sparkles size={16} /> Partner With Us
              </div>
              <h3 className="text-5xl md:text-7xl font-black leading-[1.05] tracking-tighter text-slate-900 dark:text-white">
                Building products <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 via-indigo-600 to-blue-600 animate-gradient-x">that matter.</span>
              </h3>
            </div>

            <p className={`text-slate-600 dark:text-slate-300 text-xl font-medium max-w-lg transition-all duration-1000 delay-150 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
              Ready to scale your technical infrastructure or build a new digital flagship? Let's discuss your roadmap.
            </p>

            <div className="space-y-12 pt-6">
              <div className={`flex items-start gap-8 transition-all duration-700 ease-out ${isVisible ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-10'}`} style={{ transitionDelay: '300ms' }}>
                <div className="p-5 bg-white dark:bg-slate-800 rounded-3xl border-2 border-slate-200 dark:border-slate-700 shadow-2xl shadow-blue-500/5"><Mail className="w-8 h-8 text-blue-600 dark:text-blue-400" /></div>
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">Primary Inbox</p>
                  <div className="flex items-center gap-5">
                    <p className="text-2xl md:text-3xl font-black text-slate-900 dark:text-slate-100 tracking-tight">{CONTACT_EMAIL}</p>
                    <button 
                      onClick={handleCopyEmail} 
                      className={`p-3 rounded-2xl transition-all relative flex items-center justify-center shadow-md border-2 ${isCopied ? 'bg-green-500 border-green-500 text-white scale-110 shadow-green-500/20' : 'bg-slate-50 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 hover:text-slate-900 dark:hover:text-white border-slate-300 dark:border-slate-600'}`} 
                      aria-label="Copy business email"
                    >
                      {isCopied ? <Check size={20} className="animate-in zoom-in-50 duration-300" /> : <Copy size={20} />}
                      <span className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-4 px-4 py-2.5 text-[11px] bg-slate-950 text-white rounded-2xl shadow-2xl transition-all font-black uppercase tracking-widest ${isCopied ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-2 scale-90 pointer-events-none'}`}>Copied!</span>
                    </button>
                  </div>
                </div>
              </div>

              <div className={`flex items-start gap-8 transition-all duration-700 ease-out ${isVisible ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-10'}`} style={{ transitionDelay: '450ms' }}>
                <div className="p-5 bg-white dark:bg-slate-800 rounded-3xl border-2 border-slate-200 dark:border-slate-700 shadow-2xl shadow-blue-500/5"><MapPin className="w-8 h-8 text-blue-600 dark:text-blue-400" /></div>
                <div>
