                 {project.technologies?.map(t => <span key={t} className="px-3 py-1.5 bg-slate-50 dark:bg-slate-800 rounded-xl text-xs font-bold border border-slate-200 dark:border-slate-700">{t}</span>)}
               </div>
            </div>
