              <Button onClick={() => window.open(project.link || '#', '_blank')} className="flex-1 h-14 rounded-2xl">Visit Website</Button>
              <Button variant="outline" onClick={onClose} className="flex-1 h-14 rounded-2xl">Close</Button>
