                onClick={() => document.getElementById(SectionId.CONTACT)?.scrollIntoView({ behavior: 'smooth' })}
              >
                Launch Project
                <ArrowRight className="ml-2 w-5 h-5 transition-transform group-hover:translate-x-1.5" />
