export const Portfolio: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState(() => localStorage.getItem('portfolio_cat') || ALL_CATEGORY);
  const [activeTag, setActiveTag] = useState(() => localStorage.getItem('portfolio_tag') || ALL_TAG);
  const [activeStatus, setActiveStatus] = useState(() => localStorage.getItem('portfolio_status') || ALL_STATUS);
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedProject, setSelectedProject] = useState<{ project: Project; mode: 'full' | 'quick' | 'video' } | null>(null);
  const [isFilterAnimating, setIsFilterAnimating] = useState(false);

  useEffect(() => {
    localStorage.setItem('portfolio_cat', activeCategory);
    localStorage.setItem('portfolio_tag', activeTag);
    localStorage.setItem('portfolio_status', activeStatus);
  }, [activeCategory, activeTag, activeStatus]);

  const handleFilterChange = (setter: (v: string) => void, value: string) => {
    setIsFilterAnimating(true);
    setTimeout(() => {
      setter(value);
      setCurrentPage(1);
      setTimeout(() => setIsFilterAnimating(false), 300);
    }, 300);
  };

  const resetFilters = () => {
    setIsFilterAnimating(true);
    setTimeout(() => {
      setActiveCategory(ALL_CATEGORY);
      setActiveTag(ALL_TAG);
      setActiveStatus(ALL_STATUS);
      setCurrentPage(1);
      setTimeout(() => setIsFilterAnimating(false), 300);
    }, 300);
  };

  const filteredProjects = PROJECTS.filter(p => 
    (activeCategory === ALL_CATEGORY || p.category === activeCategory) && 
    (activeTag === ALL_TAG || p.technologies?.includes(activeTag)) &&
    (activeStatus === ALL_STATUS || p.status === activeStatus)
  );

  const currentProjects = filteredProjects.slice((currentPage - 1) * PROJECTS_PER_PAGE, currentPage * PROJECTS_PER_PAGE);

  const categories = [ALL_CATEGORY, ...Array.from(new Set(PROJECTS.map(p => p.category)))];
  const tags = [ALL_TAG, ...Array.from(new Set(PROJECTS.flatMap(p => p.technologies || []))).sort()];
  const statuses = [ALL_STATUS, 'Completed', 'In Progress', 'Maintenance'];

  return (
    <section id={SectionId.PORTFOLIO} className="py-24 bg-slate-50 dark:bg-slate-950 min-h-[1000px] transition-colors duration-500 overflow-hidden relative">
      <div className="container mx-auto px-6 relative z-10">
        <div className="text-center max-w-4xl mx-auto mb-20">
          <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 text-[10px] font-black uppercase tracking-[0.2em] mb-8">
             <Rocket size={16} /> Showcase Gallery
          </div>
          <h2 className="text-5xl md:text-7xl font-black mb-8 tracking-tighter text-slate-900 dark:text-white">Engineering <br className="hidden md:block"/> Success Stories</h2>
          <p className="text-slate-600 dark:text-slate-400 text-xl font-medium mb-16 max-w-2xl mx-auto">High-performance digital products shipped for visionary global brands.</p>

          <div className="flex flex-col gap-12 items-center">
            {/* Category Filters */}
            <div className="flex flex-wrap justify-center gap-4">
              {categories.map(c => (
                <button 
                  key={c} 
                  onClick={() => handleFilterChange(setActiveCategory, c)} 
                  className={`px-8 md:px-10 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all transform hover:scale-105 active:scale-95 border-2 ${activeCategory === c ? 'bg-blue-600 border-blue-600 text-white shadow-2xl shadow-blue-500/40' : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 border-slate-200 dark:border-slate-800 hover:border-blue-400/50'}`}
                >
                  {c}
                </button>
              ))}
            </div>

            {/* Sub Filters: Status and Reset */}
            <div className="flex flex-wrap justify-center gap-6 items-center">
              <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                <div className="px-4 text-[9px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                  <Filter size={12} /> Status
                </div>
                {statuses.map(s => (
                  <button
                    key={s}
                    onClick={() => handleFilterChange(setActiveStatus, s)}
                    className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeStatus === s ? 'bg-slate-900 dark:bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-900 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                  >
                    {s === ALL_STATUS ? 'All' : s}
                  </button>
                ))}
              </div>

              <button 
                onClick={resetFilters}
                className="px-6 py-4 rounded-2xl bg-white dark:bg-slate-800 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 border-2 border-slate-200 dark:border-slate-800 transition-all transform hover:scale-105 active:scale-95 flex items-center gap-2 font-black uppercase text-[11px] tracking-widest shadow-sm group"
              >
                <RefreshCw size={14} className={`group-hover:rotate-180 transition-transform duration-700 ${isFilterAnimating ? 'animate-spin' : ''}`} /> Reset Filters
              </button>
            </div>
          </div>
        </div>

        <div className={`transition-all duration-500 transform ${isFilterAnimating ? 'opacity-0 scale-95 translate-y-8 blur-sm' : 'opacity-100 scale-100 translate-y-0'}`}>
          {currentProjects.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 mb-20">
              {currentProjects.map((p, i) => (
                <ProjectCard 
                  key={`${p.id}-${activeCategory}-${activeStatus}`} 
                  project={p} 
                  index={i} 
                  onTagClick={(tag) => handleFilterChange(setActiveTag, tag)} 
                  onSelect={(p, m) => setSelectedProject({ project: p, mode: m })} 
                />
              ))}
            </div>
          ) : (
            <div className="text-center py-40 bg-white dark:bg-slate-900/50 rounded-[4rem] border-2 border-dashed border-slate-200 dark:border-slate-800 animate-in zoom-in duration-700">
               <SearchX size={80} className="mx-auto text-slate-200 dark:text-slate-800 mb-8" />
               <p className="text-3xl font-black mb-6 text-slate-900 dark:text-white tracking-tight">Zero matches found.</p>
               <Button onClick={resetFilters} variant="primary" size="lg" className="rounded-2xl px-16 h-16 text-lg font-black">View All Work</Button>
            </div>
          )}
        </div>
      </div>
      <ProjectModal 
        project={selectedProject?.project || null} 
        mode={selectedProject?.mode || 'full'} 
        onClose={() => setSelectedProject(null)} 
      />
    </section>
  );
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  children, 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-all duration-500 focus:outline-none focus:ring-2 focus:ring-slate-400 focus:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none active:scale-[0.98]";

  const variants = {
    primary: "bg-slate-900 text-white hover:bg-slate-800 hover:scale-[1.05] hover:shadow-2xl hover:shadow-slate-500/30 dark:bg-blue-600 dark:hover:bg-blue-500 dark:hover:shadow-blue-600/40 dark:focus:ring-blue-500",
    secondary: "bg-slate-100 text-slate-900 hover:bg-slate-200 dark:bg-slate-800 dark:text-white dark:hover:bg-slate-700",
    outline: "border-2 border-slate-200 bg-transparent hover:bg-slate-900 hover:text-white hover:border-slate-900 dark:border-slate-700 dark:text-slate-100 dark:hover:bg-white dark:hover:text-slate-950 dark:hover:border-white",
    ghost: "hover:bg-slate-100 text-slate-700 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white dark:hover:bg-slate-800",
  };

  const sizes = {
    sm: "h-9 px-3 text-xs",
    md: "h-11 px-8 text-sm",
    lg: "h-14 px-10 text-base",
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

