    localStorage.setItem('portfolio_tag', activeTag);
    localStorage.setItem('portfolio_status', activeStatus);
  }, [activeCategory, activeTag, activeStatus]);

  const handleFilterChange = (setter: (v: string) => void, value: string) => {
    if (isFilterAnimating) return;
    setIsFilterAnimating(true);
    setTimeout(() => {
      setter(value);
      setCurrentPage(1);
      setTimeout(() => setIsFilterAnimating(false), 500);
    }, 400);
  };

  const resetFilters = () => {
    setIsFilterAnimating(true);
    setTimeout(() => {
      setActiveCategory(ALL_CATEGORY);
      setActiveTag(ALL_TAG);
      setActiveStatus(ALL_STATUS);
      setCurrentPage(1);
      setTimeout(() => setIsFilterAnimating(false), 500);
    }, 400);
  };

  const filteredProjects = PROJECTS.filter(p => 
    (activeCategory === ALL_CATEGORY || p.category === activeCategory) && 
    (activeTag === ALL_TAG || p.technologies?.includes(activeTag)) &&
    (activeStatus === ALL_STATUS || p.status === activeStatus)
  );

  const currentProjects = filteredProjects.slice((currentPage - 1) * PROJECTS_PER_PAGE, currentPage * PROJECTS_PER_PAGE);

  const categories = [ALL_CATEGORY, ...Array.from(new Set(PROJECTS.map(p => p.category)))];
  const tags = [ALL_TAG, ...Array.from(new Set(PROJECTS.flatMap(p => p.technologies || []))).sort()];
  const statuses = [ALL_STATUS, 'Completed', 'In Progress', 'Maintenance'];

  // Count helper
  const getCountForCategory = (cat: string) => {
    if (cat === ALL_CATEGORY) return PROJECTS.length;
    return PROJECTS.filter(p => p.category === cat).length;
  };

  const getCountForStatus = (stat: string) => {
    if (stat === ALL_STATUS) return PROJECTS.length;
    return PROJECTS.filter(p => p.status === stat).length;
  };

  return (
    <section id={SectionId.PORTFOLIO} className="py-24 bg-slate-50 dark:bg-slate-950 min-h-[1000px] transition-colors duration-500 overflow-hidden relative">
      <div className="container mx-auto px-6 relative z-10">
        <div className="text-center max-w-4xl mx-auto mb-20">
          <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 text-[10px] font-black uppercase tracking-[0.2em] mb-8 shadow-sm">
             <Rocket size={16} /> Showcase Gallery
          </div>
          <h2 className="text-5xl md:text-7xl font-black mb-8 tracking-tighter text-slate-900 dark:text-white">Engineering <br className="hidden md:block"/> Success Stories</h2>
          <p className="text-slate-600 dark:text-slate-400 text-xl font-medium mb-16 max-w-2xl mx-auto">High-performance digital products shipped for visionary global brands.</p>

          <div className="flex flex-col gap-12 items-center">
            {/* Category Filters with Counts */}
            <div className="flex flex-wrap justify-center gap-4">
              {categories.map(c => (
                <button 
                  key={c} 
                  onClick={() => handleFilterChange(setActiveCategory, c)} 
                  className={`px-8 md:px-10 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all transform hover:scale-105 active:scale-95 border-2 flex items-center gap-3 ${activeCategory === c ? 'bg-blue-600 border-blue-600 text-white shadow-2xl shadow-blue-500/40 ring-4 ring-blue-500/10' : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 border-slate-200 dark:border-slate-800 hover:border-blue-400/50'}`}
                >
                  {c}
                  <span className={`text-[9px] px-2 py-0.5 rounded-full ${activeCategory === c ? 'bg-white/20' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                    {getCountForCategory(c)}
                  </span>
                </button>
              ))}
            </div>

            {/* Sub Filters: Status and Reset */}
            <div className="flex flex-wrap justify-center gap-6 items-center">
              <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-x-auto no-scrollbar">
                <div className="px-4 text-[9px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2 whitespace-nowrap">
                  <Filter size={12} /> Status
                </div>
                {statuses.map(s => (
                  <button
                    key={s}
                    onClick={() => handleFilterChange(setActiveStatus, s)}
                    className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap flex items-center gap-2 ${activeStatus === s ? 'bg-slate-900 dark:bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-900 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                  >
                    {s === ALL_STATUS ? 'All' : s}
                    <span className={`text-[8px] opacity-60`}>({getCountForStatus(s)})</span>
                  </button>
                ))}
              </div>

              <button 
                onClick={resetFilters}
                className="px-6 py-4 rounded-2xl bg-white dark:bg-slate-800 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 border-2 border-slate-200 dark:border-slate-800 transition-all transform hover:scale-105 active:scale-95 flex items-center gap-2 font-black uppercase text-[11px] tracking-widest shadow-sm group"
              >
                <RefreshCw size={14} className={`group-hover:rotate-180 transition-transform duration-700 ${isFilterAnimating ? 'animate-spin' : ''}`} /> Reset Filters
              </button>
            </div>
          </div>
        </div>

        <div className={`transition-all duration-500 transform ${isFilterAnimating ? 'opacity-40 scale-[0.98] blur-sm' : 'opacity-100 scale-100'}`}>
          {isFilterAnimating ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 mb-20">
               {[1,2,3,4,5,6].map(i => <ProjectSkeleton key={i} />)}
            </div>
          ) : currentProjects.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 mb-20 animate-in fade-in slide-in-from-bottom-4 duration-500">
              {currentProjects.map((p, i) => (
                <ProjectCard 
                  key={`${p.id}-${activeCategory}-${activeStatus}`} 
                  project={p} 
                  index={i} 
                  onTagClick={(tag) => handleFilterChange(setActiveTag, tag)} 
                  onSelect={(p, m) => setSelectedProject({ project: p, mode: m })} 
                />
              ))}
            </div>
          ) : (
            <div className="text-center py-40 bg-white dark:bg-slate-900/50 rounded-[4rem] border-2 border-dashed border-slate-200 dark:border-slate-800 animate-in zoom-in duration-700">
               <SearchX size={80} className="mx-auto text-slate-200 dark:text-slate-800 mb-8" />
               <p className="text-3xl font-black mb-6 text-slate-900 dark:text-white tracking-tight">Zero matches found.</p>
               <Button onClick={resetFilters} variant="primary" size="lg" className="rounded-2xl px-16 h-16 text-lg font-black">View All Work</Button>
            </div>
          )}
        </div>
      </div>
      <ProjectModal 
        project={selectedProject?.project || null} 
        mode={selectedProject?.mode || 'full'} 
        onClose={() => setSelectedProject(null)} 
      />

      <style>{`
        @keyframes shimmer {
          100% { transform: translateX(100%); }
        }
      `}</style>
    </section>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Mail, MapPin, Send, AlertCircle, CheckCircle2, Copy, Check, Sparkles, RefreshCcw } from 'lucide-react';
import { Button } from './ui/Button';
import { ADDRESS, CONTACT_EMAIL } from '../constants';
import { SectionId } from '../types';

export const Contact: React.FC = () => {
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [errors, setErrors] = useState<{ name?: string; email?: string; message?: string }>({});
  const [status, setStatus] = useState<'idle' | 'sending' | 'success' | 'error'>('idle');
  const [isCopied, setIsCopied] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => { 
      if (entry.isIntersecting) { 
        setIsVisible(true); 
        observer.disconnect(); 
      } 
    }, { threshold: 0.1 });
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const handleCopyEmail = () => {
    navigator.clipboard.writeText(CONTACT_EMAIL);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const validate = () => {
    const newErrors: typeof errors = {};
    if (!formData.name.trim()) newErrors.name = 'Please provide your full identity';
    if (!formData.email.trim()) {
      newErrors.email = 'An email address is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'That email format is invalid';
    }
    if (!formData.message.trim()) newErrors.message = 'Please describe your project mission';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    setStatus('sending');

    // Simulating API call
    setTimeout(() => {
      // Simulate 5% chance of network failure for demonstration of error states
      if (Math.random() < 0.05) {
        setStatus('error');
      } else {
        setStatus('success');
        setFormData({ name: '', email: '', message: '' });
        setErrors({});
        setTimeout(() => setStatus('idle'), 6000);
      }
    }, 2000);
  };

  return (
    <section 
      ref={sectionRef} 
      id={SectionId.CONTACT} 
      className="py-24 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white transition-colors duration-500 relative overflow-hidden"
    >
      <div className="absolute top-0 right-0 w-[45%] h-full bg-blue-100/40 dark:bg-blue-900/5 -skew-x-12 transform translate-x-1/4 pointer-events-none transition-colors duration-500" />
      <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-indigo-200/30 dark:bg-indigo-900/10 rounded-full blur-[120px] pointer-events-none transition-colors duration-500" />

      <div className="container mx-auto px-6 relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-20 xl:gap-32 items-start">

          <div className="space-y-12">
            <div className={`transition-all duration-1000 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
              <div className="inline-flex items-center gap-3 px-5 py-2.5 rounded-full bg-blue-600/10 dark:bg-blue-400/10 text-blue-900 dark:text-blue-300 text-[11px] font-black uppercase tracking-[0.25em] mb-8 shadow-sm ring-1 ring-blue-500/30">
                <Sparkles size={16} className="text-blue-600" /> Partner With Us
              </div>
              <h3 className="text-5xl md:text-7xl font-black leading-[1.05] tracking-tighter text-slate-950 dark:text-white">
                Let's architect <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 via-indigo-600 to-blue-600 animate-pulse">your legacy.</span>
              </h3>
            </div>

            <p className={`text-slate-700 dark:text-slate-300 text-xl font-medium max-w-lg transition-all duration-1000 delay-150 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
              Ready to modernize your infrastructure? Connect with our senior engineers today for a strategic architecture session.
            </p>

            <div className="space-y-12 pt-6">
              <div className={`flex items-start gap-8 transition-all duration-700 ease-out ${isVisible ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-10'}`} style={{ transitionDelay: '300ms' }}>
                <div className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border-2 border-slate-200 dark:border-slate-800 shadow-xl shadow-blue-500/5 ring-1 ring-slate-100 dark:ring-slate-700">
                  <Mail className="w-8 h-8 text-blue-600 dark:text-blue-400" />
                </div>
                <div className="flex-1">
                  <p className="text-[11px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em] mb-3">Direct Correspondence</p>
                  <div className="flex flex-wrap items-center gap-4">
                    <p className="text-2xl md:text-3xl font-black text-slate-950 dark:text-slate-100 tracking-tight">{CONTACT_EMAIL}</p>
                    <button 
                      onClick={handleCopyEmail} 
                      className={`relative flex items-center justify-center p-4 rounded-2xl transition-all duration-500 border-2 ${
                        isCopied 
                        ? 'bg-green-600 border-green-600 text-white scale-110 shadow-[0_0_25px_rgba(22,163,74,0.3)]' 
                        : 'bg-white dark:bg-slate-900 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 border-slate-200 dark:border-slate-800 shadow-md'
                      }`} 
                      aria-label={isCopied ? "Email copied" : "Copy email address"}
                    >
                      {isCopied ? (
                        <Check size={22} className="animate-in zoom-in spin-in-45 duration-500 stroke-[3px]" />
                      ) : (
                        <Copy size={22} />
                      )}
                      <span className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-4 px-4 py-2 text-[10px] bg-slate-950 text-white rounded-xl shadow-2xl transition-all font-black uppercase tracking-widest ${isCopied ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2 pointer-events-none'}`}>
                        Copied To Clipboard
                      </span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className={`relative transition-all duration-1000 delay-300 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
            {/* Submission Indicator Overlay */}
            {status === 'sending' && (
              <div className="absolute inset-0 z-40 bg-white/60 dark:bg-slate-950/60 backdrop-blur-[6px] rounded-[4rem] flex flex-col items-center justify-center animate-in fade-in duration-500 border-2 border-blue-500/20 shadow-2xl">
                <div className="relative">
                  <div className="w-24 h-24 border-[6px] border-blue-600/20 border-t-blue-600 rounded-full animate-spin shadow-inner"></div>
                  <div className="absolute inset-0 flex items-center justify-center">
                    <Send size={32} className="text-blue-600 animate-pulse" />
                  </div>
                </div>
                <p className="mt-8 text-sm font-black text-blue-600 uppercase tracking-[0.25em] animate-pulse">Dispatching Mission...</p>
              </div>
            )}

            <div className={`bg-white dark:bg-slate-900 p-10 md:p-14 rounded-[4rem] border-2 border-slate-200 dark:border-slate-800 shadow-[0_60px_100px_-30px_rgba(0,0,0,0.12)] dark:shadow-none transition-all duration-700 ${status === 'sending' ? 'scale-[0.98] blur-[1px]' : 'scale-100'}`}>

              {status === 'success' ? (
                <div className="h-full flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-700 py-20">
                  <div className="w-32 h-32 bg-green-50 dark:bg-green-900/20 rounded-full flex items-center justify-center text-green-600 dark:text-green-400 mb-10 shadow-2xl shadow-green-500/10">
                    <CheckCircle2 size={64} className="stroke-[2.5px]" />
                  </div>
                  <h4 className="text-4xl font-black mb-4 text-slate-950 dark:text-white tracking-tighter">Mission Received</h4>
                  <p className="text-slate-600 dark:text-slate-400 text-lg mb-12 max-w-sm font-medium leading-relaxed">Your message has been securely delivered to our project architects.</p>
                  <Button variant="primary" size="lg" onClick={() => setStatus('idle')} className="rounded-2xl px-14 h-16 border-2 font-black text-lg transition-all active:scale-95">Send New Message</Button>
                </div>
              ) : status === 'error' ? (
                <div className="h-full flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-700 py-20">
                  <div className="w-32 h-32 bg-red-50 dark:bg-red-900/20 rounded-full flex items-center justify-center text-red-600 dark:text-red-400 mb-10 shadow-2xl shadow-red-500/10">
                    <AlertCircle size={64} className="stroke-[2.5px]" />
                  </div>
                  <h4 className="text-4xl font-black mb-4 text-slate-950 dark:text-white tracking-tighter">Transmission Failed</h4>
                  <p className="text-slate-600 dark:text-slate-400 text-lg mb-12 max-w-sm font-medium leading-relaxed">A temporary network disruption occurred. Please try resending your inquiry.</p>
                  <Button variant="primary" size="lg" onClick={() => setStatus('idle')} className="rounded-2xl px-14 h-16 border-2 font-black text-lg transition-all active:scale-95 flex items-center gap-3">
                    <RefreshCcw size={20} /> Retry Now
                  </Button>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-10" noValidate>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-4 group">
                      <label htmlFor="name-input" className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-900 dark:text-slate-100 ml-1 group-focus-within:text-blue-600 transition-colors">
                        Full Name <span className="text-blue-500 font-black">*</span>
                      </label>
                      <input 
                        type="text" id="name-input" name="name" 
                        aria-invalid={!!errors.name} 
                        aria-describedby={errors.name ? "name-error" : undefined}
                        className={`w-full bg-slate-50 dark:bg-slate-800/80 border-2 ${errors.name ? 'border-red-600 dark:border-red-500 bg-red-50/20 shadow-[0_0_15px_rgba(220,38,38,0.1)]' : 'border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600'} rounded-2xl px-7 py-5 text-slate-950 dark:text-white focus:outline-none focus:border-blue-600 dark:focus:border-blue-500 focus:ring-4 focus:ring-blue-600/10 transition-all font-bold placeholder:text-slate-400 dark:placeholder:text-slate-600 shadow-sm`} 
                        placeholder="e.g. Johnathan Doe" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} 
                      />
                      {errors.name && (
                        <p id="name-error" className="text-red-700 dark:text-red-400 text-[11px] mt-2 flex items-center gap-2 font-black animate-in fade-in slide-in-from-top-1 duration-500">
                          <AlertCircle size={14} /> {errors.name}
                        </p>
                      )}
                    </div>
                    <div className="space-y-4 group">
                      <label htmlFor="email-input" className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-900 dark:text-slate-100 ml-1 group-focus-within:text-blue-600 transition-colors">
                        Business Email <span className="text-blue-500 font-black">*</span>
                      </label>
                      <input 
                        type="email" id="email-input" name="email" 
                        aria-invalid={!!errors.email}
                        aria-describedby={errors.email ? "email-error" : undefined}
                        className={`w-full bg-slate-50 dark:bg-slate-800/80 border-2 ${errors.email ? 'border-red-600 dark:border-red-500 bg-red-50/20 shadow-[0_0_15px_rgba(220,38,38,0.1)]' : 'border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600'} rounded-2xl px-7 py-5 text-slate-950 dark:text-white focus:outline-none focus:border-blue-600 dark:focus:border-blue-500 focus:ring-4 focus:ring-blue-600/10 transition-all font-bold placeholder:text-slate-400 dark:placeholder:text-slate-600 shadow-sm`} 
                        placeholder="ceo@company.com" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} 
                      />
                      {errors.email && (
                        <p id="email-error" className="text-red-700 dark:text-red-400 text-[11px] mt-2 flex items-center gap-2 font-black animate-in fade-in slide-in-from-top-1 duration-500">
                          <AlertCircle size={14} /> {errors.email}
                        </p>
                      )}
                    </div>
                  </div>

                  <div className="space-y-4 group">
                    <label htmlFor="message-input" className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-900 dark:text-slate-100 ml-1 group-focus-within:text-blue-600 transition-colors">
                      Brief Your Mission <span className="text-blue-500 font-black">*</span>
                    </label>
                    <textarea 
                      id="message-input" name="message" 
                      aria-invalid={!!errors.message} 
                      aria-describedby={errors.message ? "message-error" : undefined}
                      rows={5}
                      className={`w-full bg-slate-50 dark:bg-slate-800/80 border-2 ${errors.message ? 'border-red-600 dark:border-red-500 bg-red-50/20 shadow-[0_0_15px_rgba(220,38,38,0.1)]' : 'border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600'} rounded-[2.5rem] px-7 py-6 text-slate-950 dark:text-white focus:outline-none focus:border-blue-600 dark:focus:border-blue-500 focus:ring-4 focus:ring-blue-600/10 transition-all resize-none font-bold placeholder:text-slate-400 dark:placeholder:text-slate-600 shadow-sm`} 
                      placeholder="What can we help you build?" value={formData.message} onChange={(e) => setFormData({...formData, message: e.target.value})} 
                    />
                    {errors.message && (
                      <p id="message-error" className="text-red-700 dark:text-red-400 text-[11px] mt-2 flex items-center gap-2 font-black animate-in fade-in slide-in-from-top-1 duration-500">
                        <AlertCircle size={14} /> {errors.message}
                      </p>
                    )}
                  </div>

                  <div className="pt-4">
                    <Button 
                      type="submit" variant="primary" size="lg" 
                      className={`w-full bg-slate-950 dark:bg-blue-600 text-white rounded-[2rem] shadow-2xl transition-all duration-500 font-black text-xl h-20 border-none group transform active:scale-[0.97] ${status === 'sending' ? 'cursor-wait opacity-60 animate-pulse' : 'hover:shadow-blue-600/40'}`} 
                      disabled={status === 'sending'}
                    >
                      {status === 'sending' ? (
                        <div className="flex items-center gap-4">
                          <div className="w-7 h-7 border-4 border-white/20 border-t-white rounded-full animate-spin"></div> 
                          Securely Dispatching...
                        </div>
                      ) : (
                        <span className="flex items-center gap-4">
                          Initiate Connection
                          <Send size={24} className="transform rotate-12 transition-transform duration-300 group-hover:translate-x-2 group-hover:-translate-y-2" />
                        </span>
                      )}
                    </Button>
                  </div>
                </form>
              )}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

import React from 'react';
import { Terminal, Github, Linkedin, Twitter, Facebook, Sun, Moon } from 'lucide-react';
import { COMPANY_NAME, NAV_ITEMS, SERVICES } from '../constants';
import { SectionId } from '../types';

interface FooterProps {
  theme: 'light' | 'dark';
  toggleTheme: () => void;
}

const SocialLink = ({ href, icon: Icon, label }: { href: string; icon: any; label: string }) => (
  <a 
    href={href} 
    className="group relative p-2 rounded-lg hover:bg-slate-800 transition-colors"
    aria-label={label}
  >
    <div className="group-hover:animate-subtle-bounce">
      <Icon size={20} className="text-slate-400 group-hover:text-white transition-colors" />
    </div>

    {/* Tooltip */}
    <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 text-xs font-medium text-white bg-slate-900 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none shadow-xl border border-slate-700 transform translate-y-2 group-hover:translate-y-0 duration-200">
      {label}
      <span className="absolute top-full left-1/2 -translate-x-1/2 -mt-px border-4 border-transparent border-t-slate-700"></span>
    </span>
  </a>
);

export const Footer: React.FC<FooterProps> = ({ theme, toggleTheme }) => {
  const handleNavClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

