  return (
    <section id={SectionId.HOME} className="relative pt-32 pb-20 md:pt-48 md:pb-32 overflow-hidden min-h-[100vh] flex items-center">

      {/* Background Video and Layers */}
      <div className="absolute top-0 left-0 w-full h-full -z-50 overflow-hidden pointer-events-none">

        {/* Full-width looping video background */}
        <video 
          autoPlay 
          loop 
          muted 
          playsInline 
          className="absolute inset-0 w-full h-full object-cover opacity-20 dark:opacity-10 transition-opacity duration-1000 scale-105"
          style={{ transform: `scale(1.05) translate(${mousePos.x * 20}px, ${mousePos.y * 20}px)` }}
          poster="https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&q=80&w=2070"
        >
          <source src="https://assets.mixkit.co/videos/preview/mixkit-digital-circuit-board-loop-animation-4424-large.mp4" type="video/mp4" />
        </video>

        {/* Dynamic Overlay Layers */}
        <div className="absolute inset-0 z-10 bg-gradient-to-b from-slate-50/95 via-slate-50/80 to-slate-50/95 dark:from-slate-950/95 dark:via-slate-950/90 dark:to-slate-950/95 transition-colors duration-500" />

        <canvas 
          ref={canvasRef} 
