                      className={`inline-block transition-all duration-[1000ms] ease-out transform ${isVisible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-full scale-95'}`}
                      style={{ transitionDelay: `${i * 150 + 600}ms` }}
                    >
