                  ))}
                </span>
              </h1>
            </div>

            <p className="text-xl md:text-3xl text-slate-700 dark:text-slate-300 max-w-2xl mx-auto lg:mx-0 leading-relaxed font-medium overflow-hidden flex flex-wrap justify-center lg:justify-start">
