                  ))}
                </span>
                <span className="block text-transparent bg-clip-text bg-gradient-to-r from-blue-600 via-indigo-600 to-sky-500 overflow-hidden py-4 -my-4">
                   {titleLine2.split(' ').map((word, i) => (
