  return (
    <section id={SectionId.HOME} className="relative pt-32 pb-20 md:pt-48 md:pb-32 overflow-hidden min-h-[100vh] flex items-center">

      {/* Background Layers */}
      <div className="absolute inset-0 -z-50 overflow-hidden pointer-events-none">
        <video autoPlay loop muted playsInline className="absolute inset-0 w-full h-full object-cover opacity-10 dark:opacity-5 transition-opacity duration-1000 scale-105" poster="https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&q=80&w=2070">
          <source src="https://assets.mixkit.co/videos/preview/mixkit-digital-circuit-board-loop-animation-4424-large.mp4" type="video/mp4" />
        </video>
        <div className="absolute inset-0 z-10 bg-gradient-to-b from-slate-50/95 via-slate-50/85 to-slate-50/95 dark:from-slate-950/98 dark:via-slate-950/90 dark:to-slate-950/98" />
        <canvas ref={canvasRef} className="absolute inset-0 z-20 opacity-40 pointer-events-none" />
        <div className="absolute top-[-15%] right-[-10%] w-[900px] h-[900px] bg-blue-500/10 dark:bg-blue-600/5 rounded-full blur-[200px] animate-float z-0" style={{ transform: `translate(${mousePos.x * -100}px, ${mousePos.y * -100}px)` }} />
      </div>

      <div className="container mx-auto px-6 relative z-30">
        <div className="flex flex-col lg:flex-row items-center gap-12 lg:gap-24">

          <div className="flex-1 space-y-12 text-center lg:text-left relative z-40">
            <div className={`inline-flex items-center gap-2 px-5 py-2.5 rounded-full bg-blue-50/90 dark:bg-blue-900/40 backdrop-blur-3xl border border-blue-200 dark:border-blue-800 text-[10px] font-black text-blue-700 dark:text-blue-400 uppercase tracking-[0.3em] shadow-sm transition-all duration-[1200ms] transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-6'}`}>
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
              Engineering High-Performance Futures
            </div>

            <div className="space-y-6">
              <h1 className="text-6xl md:text-7xl lg:text-9xl font-black text-slate-900 dark:text-white tracking-tighter leading-[1] pb-2">
                <span className="block overflow-hidden h-auto">
                  {titleLine1.split(' ').map((word, i) => (
                    <span key={i} className={`inline-block transition-all duration-[1000ms] ease-out transform ${isVisible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-full scale-90'}`} style={{ transitionDelay: `${i * 150 + 200}ms` }}>{word}&nbsp;</span>
                  ))}
                </span>
                <span className="block text-transparent bg-clip-text bg-gradient-to-r from-blue-700 via-indigo-700 to-sky-600 dark:from-blue-500 dark:via-indigo-500 dark:to-sky-400 py-4 -my-4 h-auto min-h-[1.1em] overflow-visible">
                   {titleLine2.split(' ').map((word, i) => (
