            </div>

            <p className="text-xl md:text-3xl text-slate-700 dark:text-slate-300 max-w-2xl mx-auto lg:mx-0 leading-relaxed font-medium flex flex-wrap justify-center lg:justify-start">
              {taglineWords.map((word, i) => (
                <span key={i} className={`inline-block transition-all duration-[800ms] ease-out transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`} style={{ transitionDelay: `${i * 50 + 1000}ms` }}>{word}&nbsp;</span>
              ))}
              <span className={`inline-block transition-all duration-[1200ms] delay-[1400ms] ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>High-performance software engineering combined with design thinking.</span>
            </p>

            <div className={`flex flex-col sm:flex-row items-center gap-6 justify-center lg:justify-start transition-all duration-[1000ms] delay-[1800ms] transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'} relative z-50`}>
