          {/* Right Visual Area: Innovation Animation */}
          <div className={`flex-1 w-full max-w-2xl lg:max-w-none transition-all duration-[1800ms] delay-[400ms] transform ${isVisible ? 'opacity-100 translate-x-0 rotate-0 scale-100' : 'opacity-0 translate-x-32 rotate-6 scale-90'} relative`}>
             <div className="relative group" style={{ perspective: '2000px' }}>
                <div 
                  className="relative bg-white dark:bg-slate-900 border-4 border-white dark:border-slate-800 rounded-[4rem] shadow-[0_80px_120px_-40px_rgba(0,0,0,0.25)] dark:shadow-none overflow-hidden aspect-[4/3] transform-gpu transition-all duration-700 hover:scale-[1.03] z-10 flex items-center justify-center p-12"
                  style={{ transform: `rotateY(${mousePos.x * -15}deg) rotateX(${mousePos.y * 15}deg)` }}
                >
                  {/* Custom Transformation Animation (SVG/CSS) */}
                  <div className="relative w-full h-full">
                    <div className="absolute inset-0 flex items-center justify-center opacity-20 dark:opacity-10">
