export const Services: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [activeTab, setActiveTab] = useState(TECH_DOMAINS[0].id);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);

    const handleMouseMove = (e: MouseEvent) => {
      const rect = sectionRef.current?.getBoundingClientRect();
      if (rect) {
        setMousePos({
          x: (e.clientX - (rect.left + rect.width / 2)) / (rect.width / 2),
          y: (e.clientY - (rect.top + rect.height / 2)) / (rect.height / 2),
        });
      }
    };
    window.addEventListener('mousemove', handleMouseMove);

    return () => {
      observer.disconnect();
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  const expertiseTitle = "Comprehensive solutions for digital transformation.";

  return (
    <section ref={sectionRef} id={SectionId.SERVICES} className="py-32 bg-white dark:bg-slate-950 relative transition-colors duration-300 overflow-hidden">
      <div className="container mx-auto px-6">
        <div className={`flex flex-col md:flex-row justify-between items-end mb-20 gap-8 transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] transform ${isVisible ? 'opacity-100 translate-y-0 rotate-0' : 'opacity-0 translate-y-24 rotate-[-4deg]'}`}>
          <div className="max-w-2xl relative">
            <h2 className="text-sm font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-4">Our Expertise</h2>
            <h3 
              className="text-4xl md:text-6xl font-black text-slate-950 dark:text-white leading-tight tracking-tighter cursor-default flex flex-wrap"
            >
              {expertiseTitle.split(' ').map((word, i) => (
                <span 
                  key={i} 
                  className="mr-3 transition-all duration-500 hover:text-blue-600 dark:hover:text-blue-400 hover:scale-110 inline-block"
                  style={{ 
                    transform: isVisible ? `translate(${mousePos.x * (10 + i)}px, ${mousePos.y * (10 + i)}px)` : 'none'
                  }}
                >
                  {word}
                </span>
              ))}
            </h3>
          </div>
          <p className="text-slate-900 dark:text-slate-100 max-w-md pb-2 text-xl font-bold leading-relaxed">We leverage modern architectures and industry best practices to build software that lasts.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 mb-24">
          {SERVICES.map((service, index) => (
            <div 
              key={service.id} 
              id={`service-card-${service.id}`}
              className={`group relative bg-slate-50 dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-800 rounded-[3rem] p-12 transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] hover:-translate-y-4 hover:shadow-2xl hover:shadow-blue-500/10 dark:hover:shadow-blue-900/40 hover:border-blue-500/30 ${isVisible ? 'opacity-100 translate-y-0 rotate-0 scale-100' : 'opacity-0 translate-y-32 rotate-[-12deg] scale-90'}`}
              style={{ transitionDelay: `${index * 120}ms` }}
            >
              <div className="w-20 h-20 shrink-0 bg-white dark:bg-slate-800 rounded-3xl flex items-center justify-center text-slate-900 dark:text-white shadow-xl mb-10 transition-all duration-700 group-hover:bg-blue-600 group-hover:text-white group-hover:scale-115 group-hover:shadow-blue-500/40">
                <div className="transition-all duration-500 group-hover:animate-slow-pulse group-hover:rotate-12">
