              <h4 className="text-2xl font-black text-slate-950 dark:text-white mb-6 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors tracking-tight">{service.title}</h4>
              <p className="text-slate-700 dark:text-slate-300 mb-10 text-base leading-relaxed font-semibold">{service.description}</p>

              <div className="flex flex-wrap gap-2.5">
                {service.features.map((feature, idx) => (
                  <span 
                    key={idx} 
                    className={`px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-slate-300 shadow-sm transition-all duration-500 transform scale-75 opacity-0 translate-y-4 group-hover:scale-100 group-hover:opacity-100 group-hover:translate-y-0 hover:bg-blue-100 dark:hover:bg-blue-900/30 hover:border-blue-400 dark:hover:border-blue-600 hover:text-blue-700 dark:hover:text-blue-200`}
                    style={{ transitionDelay: `${index * 120 + (idx + 1) * 80}ms` }}
                  >
                    {feature}
                  </span>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Technology Ecosystem Section */}
        <div className={`mt-32 transition-all duration-1000 delay-300 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
