      >
        <div className="bg-white/50 dark:bg-slate-900/50 p-6 rounded-3xl backdrop-blur-xl border border-white/20 dark:border-slate-800/50 shadow-2xl">
          <Code2 size={64} strokeWidth={1.5} />
