        }
        draw() {
          if (!ctx) return;
          const isDark = document.documentElement.classList.contains('dark');
          ctx.fillStyle = isDark ? 'rgba(56, 189, 248, 0.25)' : 'rgba(14, 165, 233, 0.15)';
