  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [scrollY, setScrollY] = useState(0);
  const [isVisible, setIsVisible] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const scrollToContact = () => {
    document.getElementById(SectionId.CONTACT)?.scrollIntoView({ behavior: 'smooth' });
  };

  const scrollToServices = () => {
    document.getElementById(SectionId.SERVICES)?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    setIsVisible(true);

    const handleScroll = () => {
      setScrollY(window.scrollY);
    };

    const handleMouseMove = (e: MouseEvent) => {
      setMousePos({
        x: (e.clientX / window.innerWidth - 0.5) * 2,
        y: (e.clientY / window.innerHeight - 0.5) * 2,
      });
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    window.addEventListener('mousemove', handleMouseMove);

    // Canvas Animation
    const canvas = canvasRef.current;
    if (canvas) {
      const ctx = canvas.getContext('2d');
      let particles: Particle[] = [];
      let animationFrameId: number;
      let width = window.innerWidth;
      let height = window.innerHeight;

      const resize = () => {
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = width;
        canvas.height = height;
        init();
      };

      class Particle {
        x: number;
        y: number;
        size: number;
        baseX: number;
        baseY: number;
        speedX: number;
        speedY: number;

        constructor() {
          this.x = Math.random() * width;
          this.y = Math.random() * height;
          this.size = Math.random() * 2 + 1;
          this.baseX = this.x;
          this.baseY = this.y;
          this.speedX = Math.random() * 0.5 - 0.25;
          this.speedY = Math.random() * 0.5 - 0.25;
        }

        update(mouseData: {x: number, y: number}, scrollOffset: number) {
          this.x += this.speedX;
          this.y += this.speedY;

          // Scroll Parallax
          const parallaxY = this.y - scrollOffset * 0.2;

          // Mouse Interaction
          const dx = mouseData.x - this.x;
          const dy = mouseData.y - parallaxY; // Use parallax Y for interaction calculation relative to viewport
          const distance = Math.sqrt(dx * dx + dy * dy);
          const maxDistance = 150;

          if (distance < maxDistance) {
            const forceDirectionX = dx / distance;
            const forceDirectionY = dy / distance;
            const force = (maxDistance - distance) / maxDistance;
            const directionX = forceDirectionX * force * 2;
            const directionY = forceDirectionY * force * 2;
            this.x -= directionX;
            this.y -= directionY;
          }

          // Boundary check
          if (this.x > width) this.x = 0;
          if (this.x < 0) this.x = width;
          if (this.y > height) this.y = 0;
          if (this.y < 0) this.y = height;
        }

        draw(ctx: CanvasRenderingContext2D, scrollOffset: number, isDark: boolean) {
          ctx.fillStyle = isDark ? 'rgba(96, 165, 250, 0.5)' : 'rgba(3, 105, 161, 0.4)';
          ctx.beginPath();
          // Adjust drawing Y by scroll offset for parallax
          ctx.arc(this.x, this.y - scrollOffset * 0.2, this.size, 0, Math.PI * 2);
          ctx.closePath();
          ctx.fill();
        }
      }

      const init = () => {
        particles = [];
        const particleCount = Math.min(100, (width * height) / 15000);
        for (let i = 0; i < particleCount; i++) {
          particles.push(new Particle());
        }
      };

      const animate = () => {
        if (!ctx) return;
        ctx.clearRect(0, 0, width, height);

        const isDark = document.documentElement.classList.contains('dark');
        const currentMouseX = (mousePos.x / 2 + 0.5) * width;
        const currentMouseY = (mousePos.y / 2 + 0.5) * height; // Rough approximation relative to viewport

        // Update and Draw Particles
        particles.forEach(p => {
          p.update({x: currentMouseX, y: currentMouseY + scrollY}, scrollY); // Adjust mouse Y to document coords
          p.draw(ctx, scrollY, isDark);
        });

        // Draw Connections
        const maxDistance = 150;
        for (let i = 0; i < particles.length; i++) {
          for (let j = i; j < particles.length; j++) {
            const dx = particles[i].x - particles[j].x;
            const dy = (particles[i].y - scrollY * 0.2) - (particles[j].y - scrollY * 0.2);
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance < maxDistance) {
              const opacity = 1 - (distance / maxDistance);
              ctx.strokeStyle = isDark 
                ? `rgba(96, 165, 250, ${opacity * 0.15})` 
                : `rgba(3, 105, 161, ${opacity * 0.1})`;
              ctx.lineWidth = 1;
              ctx.beginPath();
              ctx.moveTo(particles[i].x, particles[i].y - scrollY * 0.2);
              ctx.lineTo(particles[j].x, particles[j].y - scrollY * 0.2);
              ctx.stroke();
            }
          }
        }

        animationFrameId = requestAnimationFrame(animate);
      };

      window.addEventListener('resize', resize);
      resize();
      init();
      animate();

      return () => {
        window.removeEventListener('resize', resize);
        window.removeEventListener('scroll', handleScroll);
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(animationFrameId);
      };
    }

    return () => {
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, [mousePos]); // Re-bind if mousePos logic needs it, though refs handle it usually. 

