            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 min-h-[400px]">
          {filteredProjects.length > 0 ? filteredProjects.map((project, index) => (
            <div 
