          onClick={(e) => e.stopPropagation()}
        >
          <social.icon size={16} />
        </a>
      ))}
    </div>
  );
};

export const Portfolio: React.FC = () => {
  const [filter, setFilter] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');
  const [isVisible, setIsVisible] = useState(false);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const sectionRef = useRef<HTMLElement>(null);

  const categories = ['All', ...new Set(PROJECTS.map(p => p.category))];
  const statuses = ['All', 'Completed', 'In Progress', 'Maintenance'];

  const getCategoryCount = (cat: string) => {
    return PROJECTS.filter(p => (cat === 'All' || p.category === cat) && (statusFilter === 'All' || p.status === statusFilter)).length;
  };

  const getStatusCount = (stat: string) => {
    return PROJECTS.filter(p => (stat === 'All' || p.status === stat) && (filter === 'All' || p.category === filter)).length;
  };

  const resetFilters = () => {
    setFilter('All');
    setStatusFilter('All');
  };

  const filteredProjects = PROJECTS.filter(p => 
    (filter === 'All' || p.category === filter) && 
    (statusFilter === 'All' || p.status === statusFilter)
  );

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const handleProjectInteraction = (project: Project) => {
    if (project.caseStudyUrl) {
      window.open(project.caseStudyUrl, '_blank');
    } else {
      setSelectedProject(project);
    }
  };

  const [activeAnimate, setActiveAnimate] = useState<string | null>(null);

  const applyFilter = (type: 'cat' | 'stat', val: string) => {
    setActiveAnimate(val);
    if (type === 'cat') setFilter(val);
    else setStatusFilter(val);
    setTimeout(() => setActiveAnimate(null), 300);
  };

  return (
    <section ref={sectionRef} id={SectionId.PORTFOLIO} className="py-32 bg-slate-50 dark:bg-slate-950 transition-colors duration-300 relative overflow-hidden">
      <div className="container mx-auto px-6">
        <div className={`flex flex-col lg:flex-row justify-between items-end mb-20 gap-8 transition-all duration-1000 transform-gpu ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
          <div className="max-w-2xl">
            <h2 className="text-sm font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-4">Our Portfolio</h2>
            <h3 className="text-4xl md:text-6xl font-black text-slate-950 dark:text-white tracking-tighter leading-tight">Engineering excellence in every pixel.</h3>
          </div>

          <div className="flex flex-col gap-6 w-full lg:w-auto">
            {/* Category Filter */}
            <div className="flex flex-wrap gap-2">
              <span className="w-full text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-2">
                <Filter size={12} /> Categories
              </span>
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => applyFilter('cat', cat)}
                  aria-label={`Filter by ${cat} category. ${getCategoryCount(cat)} projects available.`}
                  aria-pressed={filter === cat}
                  className={`group px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all duration-500 flex items-center gap-2 active:scale-95 transform-gpu ${
                    filter === cat 
                      ? 'bg-slate-950 text-white dark:bg-blue-600 shadow-xl ring-2 ring-slate-950 dark:ring-blue-600 ring-offset-2 dark:ring-offset-slate-950 scale-105' 
                      : 'bg-white dark:bg-slate-900 text-slate-500 hover:text-slate-950 dark:hover:text-white border border-slate-200 dark:border-slate-800 hover:scale-105 hover:bg-slate-50 dark:hover:bg-slate-800'
                  } ${activeAnimate === cat ? 'animate-[subtle-bounce_0.3s_ease-in-out]' : ''}`}
                >
                  {cat}
                  <span 
                    aria-label={`${getCategoryCount(cat)} items`}
                    className={`px-2 py-0.5 rounded-md text-[9px] min-w-[20px] text-center transition-colors font-black ${filter === cat ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 group-hover:bg-slate-200 dark:group-hover:bg-slate-700'}`}
                  >
                    {getCategoryCount(cat)}
                  </span>
                </button>
              ))}
            </div>

            {/* Status Filter */}
            <div className="flex flex-wrap gap-2">
              <span className="w-full text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-2">
                <CheckCircle size={12} /> Project Status
              </span>
              {statuses.map((stat) => (
                <button
                  key={stat}
                  onClick={() => applyFilter('stat', stat)}
                  aria-label={`Filter by ${stat} status. ${getStatusCount(stat)} projects available.`}
                  aria-pressed={statusFilter === stat}
                  className={`group px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all duration-500 flex items-center gap-2 active:scale-95 transform-gpu ${
                    statusFilter === stat 
                      ? 'bg-blue-600 text-white shadow-xl ring-2 ring-blue-600 ring-offset-2 dark:ring-offset-slate-950 scale-105' 
                      : 'bg-white dark:bg-slate-900 text-slate-500 hover:text-slate-950 dark:hover:text-white border border-slate-200 dark:border-slate-800 hover:scale-105 hover:bg-slate-50 dark:hover:bg-slate-800'
                  } ${activeAnimate === stat ? 'animate-[subtle-bounce_0.3s_ease-in-out]' : ''}`}
                >
                  {stat}
                  <span 
                    aria-label={`${getStatusCount(stat)} items`}
                    className={`px-2 py-0.5 rounded-md text-[9px] min-w-[20px] text-center transition-colors font-black ${statusFilter === stat ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 group-hover:bg-slate-200 dark:group-hover:bg-slate-700'}`}
                  >
                    {getStatusCount(stat)}
                  </span>
                </button>
              ))}

              {(filter !== 'All' || statusFilter !== 'All') && (
                <button 
                  onClick={resetFilters}
                  aria-label="Clear all active filters"
                  className="flex items-center gap-2 px-5 py-2.5 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-red-100 dark:hover:bg-red-900/40 transition-all animate-in fade-in zoom-in duration-300 active:scale-95 shadow-sm"
                >
                  <RotateCcw size={12} /> Reset Filters
                </button>
              )}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 min-h-[400px]">
          {filteredProjects.length > 0 ? filteredProjects.map((project, index) => (
            <div 
              key={project.id}
              className={`group bg-white dark:bg-slate-900 rounded-[2.5rem] overflow-hidden border border-slate-200 dark:border-slate-800 transition-all duration-500 ease-out hover:shadow-2xl hover:scale-[1.02] hover:-translate-y-2 dark:hover:shadow-blue-900/20 transform-gpu ${isVisible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-24 scale-95'}`}
              style={{ transitionDelay: `${index * 80}ms` }}
            >
              <div className="aspect-video overflow-hidden relative cursor-pointer" onClick={() => handleProjectInteraction(project)}>
                <img 
                  src={project.imageUrl} 
                  alt={project.title} 
                  loading="lazy"
                  className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110 group-hover:blur-[3px]"
                />
                <div className="absolute inset-0 bg-slate-900/20 group-hover:bg-slate-900/90 transition-all duration-500 backdrop-blur-0 group-hover:backdrop-blur-sm border-2 border-transparent group-hover:border-white/10 rounded-[2.5rem]" />

                <div className="absolute inset-0 flex flex-col items-center justify-center p-8 opacity-0 group-hover:opacity-100 transition-all duration-500 ease-out">
                   <div className="transform translate-y-8 group-hover:translate-y-0 transition-all duration-500 delay-100 space-y-5 text-center px-4 w-full">
                     <p className="text-white text-sm font-bold leading-relaxed mb-6 line-clamp-2 drop-shadow-md opacity-0 group-hover:opacity-100 transition-opacity duration-700 delay-200">
                       {project.description}
                     </p>

                     <div className="flex flex-col items-center gap-4">
                        <button 
                          onClick={(e) => { e.stopPropagation(); handleProjectInteraction(project); }}
                          className="flex items-center justify-center gap-3 px-8 py-3.5 bg-white text-slate-950 rounded-2xl font-black text-xs uppercase tracking-widest hover:scale-110 active:scale-95 transition-all shadow-2xl ring-2 ring-white/20 border-none outline-none"
                          aria-label={`View details for ${project.title}`}
                        >
                          <Eye size={18} /> {project.caseStudyUrl ? 'Open Case Study' : 'View Details'}
                        </button>

                        <ShareButtons project={project} />
                     </div>
                   </div>
                </div>

                <div className="absolute top-6 left-6 transition-opacity duration-300 group-hover:opacity-0">
                  <span className="px-4 py-2 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md rounded-full text-[10px] font-black uppercase tracking-widest text-blue-600 dark:text-blue-400 shadow-xl border border-white/10">
                    {project.category}
                  </span>
                </div>
              </div>

              <div className="p-10">
                <div className="flex justify-between items-start mb-6">
                  <h4 
                    className="text-2xl font-black text-slate-950 dark:text-white tracking-tight group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors cursor-pointer" 
                    onClick={() => handleProjectInteraction(project)}
                  >
                    {project.title}
                  </h4>
                  <div className="flex flex-col items-end gap-2">
                    {project.status === 'Completed' ? (
                      <div className="flex items-center gap-1.5 px-3 py-1 bg-green-50 dark:bg-green-900/20 rounded-full border border-green-100 dark:border-green-800/50">
                        <CheckCircle size={14} className="text-green-600 dark:text-green-400" />
                        <span className="text-[9px] font-black uppercase text-green-700 dark:text-green-300">Done</span>
                      </div>
                    ) : (
                      <div className="flex items-center gap-1.5 px-3 py-1 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-100 dark:border-blue-800/50">
                        <span className="text-[9px] font-black uppercase text-blue-600 dark:text-blue-300">{project.status}</span>
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex flex-wrap gap-2.5 mb-8">
                  {project.technologies?.slice(0, 3).map(tech => (
                    <div 
                      key={tech} 
                      className="relative group/tech"
                    >
                      <span className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest flex items-center gap-1.5 px-3 py-1.5 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-700 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors">
                        <Tag size={10} /> {tech}
                      </span>
                      {/* Tooltip */}
                      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 bg-slate-950 text-white text-[10px] font-black uppercase rounded-lg opacity-0 group-hover/tech:opacity-100 transition-all pointer-events-none whitespace-nowrap shadow-2xl border border-slate-800 z-20 translate-y-1 group-hover/tech:translate-y-0">
                        {tech}
                        <div className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent border-t-slate-950"></div>
                      </div>
                    </div>
                  ))}
                  {(project.technologies?.length || 0) > 3 && (
                     <span className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest flex items-center px-2 py-1.5">
                       +{ (project.technologies?.length || 0) - 3 } more
                     </span>
                  )}
                </div>

                <div className="flex items-center justify-between pt-8 border-t border-slate-100 dark:border-slate-800">
                  <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-[10px] font-black uppercase tracking-wider">
                    <Clock size={14} /> {project.duration || '3-4 Months'}
                  </div>
                  <button 
                    onClick={() => handleProjectInteraction(project)}
                    className="text-blue-600 dark:text-blue-400 text-xs font-black uppercase tracking-[0.2em] hover:translate-x-2 transition-transform flex items-center gap-2 group/cta" 
                    aria-label={`View comprehensive case study for ${project.title}`}
                  >
                    Case Study <ChevronRight size={14} className="group-hover/cta:translate-x-1 transition-transform" />
                  </button>
                </div>
              </div>
            </div>
          )) : (
            <div className="col-span-full flex flex-col items-center justify-center py-32 text-slate-400 animate-in fade-in zoom-in duration-500">
               <RotateCcw size={48} className="opacity-20 mb-8" />
               <p className="text-xl font-bold text-slate-900 dark:text-white mb-2 text-glow">No matching engineering artifacts.</p>
               <button onClick={resetFilters} aria-label="Clear filters and show all projects" className="mt-8 px-10 py-4 bg-slate-950 dark:bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest text-sm hover:scale-110 active:scale-95 transition-all shadow-2xl">Clear all filters</button>
            </div>
          )}
        </div>
      </div>

      {selectedProject && <ProjectModal project={selectedProject} onClose={() => setSelectedProject(null)} />}
    </section>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Send, AlertCircle, CheckCircle2, Copy, Check, Sparkles, RefreshCcw, MapPin, Navigation, Loader2 } from 'lucide-react';
import { Button } from './ui/Button';
import { CONTACT_EMAIL, ADDRESS } from '../constants';
import { SectionId } from '../types';

export const Contact: React.FC = () => {
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [errors, setErrors] = useState<{ name?: string; email?: string; message?: string }>({});
  const [status, setStatus] = useState<'idle' | 'sending' | 'success' | 'error'>('idle');
  const [isCopied, setIsCopied] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => { if (entry.isIntersecting) { setIsVisible(true); observer.disconnect(); } }, { threshold: 0.1 });
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const handleCopyEmail = () => {
    navigator.clipboard.writeText(CONTACT_EMAIL);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const validate = () => {
    const newErrors: typeof errors = {};
    if (!formData.name.trim()) newErrors.name = 'Identification is required';
    if (!formData.email.trim()) { 
      newErrors.email = 'A business email is required'; 
    } 
    else if (!/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(formData.email)) { 
      newErrors.email = 'Please provide a valid email format (e.g. name@company.com)'; 
    }
    if (!formData.message.trim()) newErrors.message = 'Please provide a project mission overview';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    setStatus('sending');
    setTimeout(() => {
      if (Math.random() < 0.02) { setStatus('error'); } 
      else { 
        setStatus('success'); 
        setFormData({ name: '', email: '', message: '' }); 
        setErrors({}); 
        setTimeout(() => setStatus('idle'), 8000); 
      }
    }, 2500);
  };

  const mapUrl = `https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3652.123456789012!2d90.3644321!3d23.7431234!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zMjPCsDQ0JzM1LjIiTiA5MMKwMjEnNTEuOSJF!5e0!3m2!1sen!2sbd!4v1234567890123`;
  const directionsUrl = `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(ADDRESS)}`;

  return (
    <section ref={sectionRef} id={SectionId.CONTACT} className="py-24 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white transition-colors duration-500 relative overflow-hidden">
      <div className="absolute top-0 right-0 w-[45%] h-full bg-blue-100/40 dark:bg-blue-900/5 -skew-x-12 transform translate-x-1/4 pointer-events-none" />
      <div className="container mx-auto px-6 relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-20 xl:gap-32 items-start mb-24">
          <div className="space-y-12">
            <div className={`transition-all duration-1000 ease-out ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
              <div className="inline-flex items-center gap-3 px-5 py-2.5 rounded-full bg-blue-600/10 dark:bg-blue-400/10 text-blue-900 dark:text-blue-300 text-[11px] font-black uppercase tracking-[0.25em] mb-8 ring-1 ring-blue-500/30 shadow-sm">
                <Sparkles size={16} className="text-blue-600" /> Start Your Evolution
              </div>
              <h3 className="text-5xl md:text-7xl font-black leading-[1.05] tracking-tighter text-slate-950 dark:text-white drop-shadow-sm">Let's build <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 via-indigo-600 to-blue-600 animate-pulse">industrial software.</span></h3>
            </div>
            <p className="text-slate-700 dark:text-slate-300 text-xl font-medium max-w-lg leading-relaxed">Connect with our senior engineering team to discuss your infrastructure needs.</p>

            <div className="space-y-6">
              <div className="flex flex-wrap items-center gap-4">
                <p className="text-2xl md:text-3xl font-black text-slate-950 dark:text-slate-100 tracking-tight drop-shadow-sm">{CONTACT_EMAIL}</p>
                <button onClick={handleCopyEmail} className={`p-4 rounded-2xl transition-all border-2 ${isCopied ? 'bg-green-600 border-green-600 text-white shadow-2xl scale-110' : 'bg-white dark:bg-slate-900 text-slate-400 hover:text-blue-600 border-slate-300 dark:border-slate-700 focus:outline-none focus:ring-4 focus:ring-blue-500/20'}`} aria-label="Copy email address">
                  {isCopied ? <Check size={22} className="animate-in zoom-in duration-500" /> : <Copy size={22} />}
                </button>
              </div>

              <div className="flex items-start gap-4 p-8 bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 rounded-3xl shadow-sm hover:shadow-md transition-all group">
                 <div className="w-12 h-12 rounded-xl bg-blue-50 dark:bg-blue-900/30 flex items-center justify-center text-blue-600 shrink-0 group-hover:scale-110 transition-transform">
                    <MapPin size={24} />
                 </div>
                 <div>
                    <p className="text-xs font-black uppercase tracking-widest text-slate-500 dark:text-slate-400 mb-1">HQ Studio</p>
                    <p className="font-bold text-slate-900 dark:text-slate-100 leading-relaxed text-lg">{ADDRESS}</p>
                 </div>
              </div>

              {/* Embedded Map */}
              <div className="w-full h-64 md:h-80 rounded-3xl overflow-hidden border-2 border-slate-200 dark:border-slate-800 shadow-xl mt-6">
                <iframe 
                  src={mapUrl} 
                  width="100%" 
                  height="100%" 
                  style={{ border: 0 }} 
                  allowFullScreen 
                  loading="lazy" 
                  referrerPolicy="no-referrer-when-downgrade"
                  title="OITS Dhaka Location"
                  className="grayscale hover:grayscale-0 transition-all duration-700"
                />
              </div>
            </div>
          </div>

          <div className={`relative transition-all duration-1000 delay-300 ease-out transform-gpu ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
            <div className={`relative bg-white dark:bg-slate-900 p-10 md:p-14 rounded-[4rem] border-2 border-slate-200 dark:border-slate-800 shadow-2xl transition-all duration-700 overflow-hidden ${status === 'sending' ? 'scale-[0.98]' : 'scale-100'}`}>

              {status === 'sending' && (
                <div className="absolute inset-0 z-50 bg-white/70 dark:bg-slate-900/85 backdrop-blur-[6px] flex flex-col items-center justify-center animate-in fade-in duration-500">
                  <div className="relative mb-10">
                    <Loader2 size={100} className="text-blue-600 animate-spin stroke-[1.5px]" />
                    <div className="absolute inset-0 bg-blue-600/20 blur-3xl rounded-full scale-150 animate-pulse"></div>
                  </div>
                  <div className="text-center space-y-3">
                    <p className="text-3xl font-black text-slate-950 dark:text-white tracking-tighter">Establishing Link...</p>
                    <p className="text-sm text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.3em] animate-pulse">Encrypting Payload</p>
                  </div>
                </div>
              )}

              {status === 'success' ? (
                <div className="text-center py-20 animate-in zoom-in-95 duration-700">
                  <div className="w-32 h-32 bg-green-50 dark:bg-green-900/20 rounded-full flex items-center justify-center text-green-600 dark:text-green-400 mx-auto mb-10 shadow-2xl shadow-green-500/10 ring-4 ring-green-500/10"><CheckCircle2 size={64} className="stroke-[2.5px]" /></div>
                  <h4 className="text-4xl font-black mb-4 text-slate-950 dark:text-white tracking-tighter text-glow">Packet Delivered</h4>
                  <p className="text-slate-600 dark:text-slate-300 text-lg mb-10 max-w-xs mx-auto">Our engineering leads will respond shortly.</p>
                  <Button variant="primary" size="lg" onClick={() => setStatus('idle')} className="rounded-2xl px-14 h-16 border-2 font-black text-lg shadow-xl shadow-green-500/5">Send New Inquiry</Button>
                </div>
              ) : status === 'error' ? (
                <div className="text-center py-20 animate-in zoom-in-95 duration-700">
                  <div className="w-32 h-32 bg-red-50 dark:bg-red-900/20 rounded-full flex items-center justify-center text-red-600 dark:text-red-400 mx-auto mb-10 shadow-2xl shadow-red-500/10"><AlertCircle size={64} className="stroke-[2.5px]" /></div>
                  <h4 className="text-4xl font-black mb-4 text-slate-950 dark:text-white tracking-tighter">Transmission Failed</h4>
                  <p className="text-slate-600 dark:text-slate-400 text-lg mb-12 max-w-sm mx-auto font-medium">Network timeout. Please retry the connection.</p>
                  <Button variant="primary" size="lg" onClick={() => setStatus('idle')} className="rounded-2xl px-14 h-16 border-2 font-black text-lg flex items-center gap-3"><RefreshCcw size={20} /> Re-initiate</Button>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-10" noValidate>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-4 group">
                      <label htmlFor="name-input" className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-800 dark:text-slate-200 ml-1 group-focus-within:text-blue-600 transition-colors cursor-pointer">Your Identity <span className="text-blue-500">*</span></label>
                      <input 
                        type="text" 
                        id="name-input" 
                        name="name" 
                        autoComplete="name"
                        aria-invalid={!!errors.name} 
                        className={`w-full bg-slate-50 dark:bg-slate-950 border-2 ${errors.name ? 'border-red-500 focus:border-red-500' : 'border-slate-400 dark:border-slate-600 focus:border-blue-600'} rounded-2xl px-7 py-5 text-slate-950 dark:text-white focus:outline-none focus:ring-4 focus:ring-blue-600/20 transition-all font-bold shadow-sm placeholder:text-slate-400 dark:placeholder:text-slate-600`} 
                        placeholder="John Doe" 
                        value={formData.name} 
                        onChange={(e) => setFormData({...formData, name: e.target.value})} 
                      />
                      {errors.name && (
                        <p className="text-red-600 dark:text-red-400 text-[11px] mt-2 flex items-center gap-2 font-black animate-in fade-in slide-in-from-top-1 duration-300">
                          <AlertCircle size={14} /> {errors.name}
                        </p>
                      )}
                    </div>
                    <div className="space-y-4 group">
                      <label htmlFor="email-input" className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-800 dark:text-slate-200 ml-1 group-focus-within:text-blue-600 transition-colors cursor-pointer">Business Email <span className="text-blue-500">*</span></label>
                      <input 
                        type="email" 
                        id="email-input" 
                        name="email" 
                        autoComplete="email"
                        aria-invalid={!!errors.email} 
                        className={`w-full bg-slate-50 dark:bg-slate-950 border-2 ${errors.email ? 'border-red-500 focus:border-red-500' : 'border-slate-400 dark:border-slate-600 focus:border-blue-600'} rounded-2xl px-7 py-5 text-slate-950 dark:text-white focus:outline-none focus:ring-4 focus:ring-blue-600/20 transition-all font-bold shadow-sm placeholder:text-slate-400 dark:placeholder:text-slate-600`} 
                        placeholder="ceo@company.com" 
                        value={formData.email} 
                        onChange={(e) => setFormData({...formData, email: e.target.value})} 
                      />
                      {errors.email && (
                        <p className="text-red-600 dark:text-red-400 text-[11px] mt-2 flex items-center gap-2 font-black animate-in fade-in slide-in-from-top-1 duration-300">
                          <AlertCircle size={14} /> {errors.email}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="space-y-4 group">
                    <label htmlFor="message-input" className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-800 dark:text-slate-200 ml-1 group-focus-within:text-blue-600 transition-colors cursor-pointer">Brief Your Mission <span className="text-blue-500">*</span></label>
                    <textarea 
                      id="message-input" 
                      name="message" 
                      aria-invalid={!!errors.message} 
                      rows={5} 
                      className={`w-full bg-slate-50 dark:bg-slate-950 border-2 ${errors.message ? 'border-red-500 focus:border-red-500' : 'border-slate-400 dark:border-slate-600 focus:border-blue-600'} rounded-[2.5rem] px-7 py-6 text-slate-950 dark:text-white focus:outline-none focus:ring-4 focus:ring-blue-600/20 transition-all resize-none font-bold shadow-sm placeholder:text-slate-400 dark:placeholder:text-slate-600`} 
                      placeholder="What are we building?" 
                      value={formData.message} 
                      onChange={(e) => setFormData({...formData, message: e.target.value})} 
                    />
                    {errors.message && (
                      <p className="text-red-600 dark:text-red-400 text-[11px] mt-2 flex items-center gap-2 font-black animate-in fade-in slide-in-from-top-1 duration-300">
                        <AlertCircle size={14} /> {errors.message}
                      </p>
                    )}
                  </div>
                  <div className="pt-4">
                    <Button 
                      type="submit" 
                      variant="primary" 
                      size="lg" 
                      className={`w-full font-black text-xl h-20 active:scale-95 shadow-[0_20px_40px_-10px_rgba(0,0,0,0.5)] dark:shadow-[0_20px_40px_-10px_rgba(37,99,235,0.4)] bg-slate-950 hover:bg-slate-800 dark:bg-blue-600 dark:hover:bg-blue-500 ${status === 'sending' ? 'cursor-wait opacity-60' : 'hover:scale-[1.02]'}`} 
                      disabled={status === 'sending'}
                    >
                      {status === 'sending' ? (
                        <div className="flex items-center gap-4 animate-pulse">
                          <Loader2 className="animate-spin" size={24} /> 
                          Establishing Link...
                        </div>
                      ) : (
                        <span className="flex items-center gap-4 group">
                          Initiate Connection 
                          <Send size={24} className="transform rotate-12 transition-transform duration-300 group-hover:translate-x-2 group-hover:-translate-y-2" />
                        </span>
                      )}
                    </Button>
                  </div>
                </form>
              )}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

import React from 'react';
import { Terminal, Github, Linkedin, Twitter, Facebook, Sun, Moon, MapPin } from 'lucide-react';
import { COMPANY_NAME, NAV_ITEMS, SERVICES, ADDRESS } from '../constants';
import { SectionId } from '../types';

interface FooterProps {
  theme: 'light' | 'dark';
  toggleTheme: () => void;
}

const SocialLink = ({ href, icon: Icon, label }: { href: string; icon: any; label: string }) => (
  <a 
    href={href} 
    className="group relative p-2 rounded-lg hover:bg-slate-800 transition-colors"
    aria-label={`Visit our ${label} profile`}
  >
    <div className="group-hover:animate-subtle-bounce">
      <Icon size={20} className="text-slate-400 group-hover:text-white transition-colors" />
    </div>

    {/* Tooltip */}
    <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 text-xs font-medium text-white bg-slate-900 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none shadow-xl border border-slate-700 transform translate-y-2 group-hover:translate-y-0 duration-200">
      {label}
      <span className="absolute top-full left-1/2 -translate-x-1/2 -mt-px border-4 border-transparent border-t-slate-700"></span>
    </span>
  </a>
);

export const Footer: React.FC<FooterProps> = ({ theme, toggleTheme }) => {
  const handleNavClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleServiceClick = (e: React.MouseEvent<HTMLAnchorElement>, serviceId: string) => {
    e.preventDefault();
    const element = document.getElementById(`service-card-${serviceId}`);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } else {
      document.getElementById(SectionId.SERVICES)?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <footer className="bg-slate-950 text-slate-300 py-16 border-t border-slate-800" aria-label="Site footer">
      <div className="container mx-auto px-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12 mb-12">

          <div className="space-y-6">
            <a href={`#${SectionId.HOME}`} className="flex items-center gap-2 text-white" onClick={(e) => handleNavClick(e, `#${SectionId.HOME}`)} aria-label={`${COMPANY_NAME} home - scroll to top`}>
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
                <Terminal size={16} className="text-white" />
              </div>
              <span className="text-xl font-bold">{COMPANY_NAME}</span>
            </a>
            <p className="text-sm leading-relaxed text-slate-400">
              Empowering businesses through innovative software solutions. Your digital transformation partner.
            </p>

            <a 
              href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(ADDRESS)}`} 
              target="_blank" 
              rel="noopener noreferrer"
              className="flex items-start gap-3 text-sm text-slate-400 hover:text-white transition-colors group"
            >
              <MapPin size={18} className="mt-0.5 text-blue-500 group-hover:text-blue-400" />
              <span>{ADDRESS}</span>
            </a>

            <div className="flex gap-2">
              <SocialLink href="#" icon={Github} label="GitHub" />
              <SocialLink href="#" icon={Linkedin} label="LinkedIn" />
              <SocialLink href="#" icon={Twitter} label="Twitter" />
              <SocialLink href="#" icon={Facebook} label="Facebook" />
            </div>

            <div className="pt-2">
               <button
                  onClick={toggleTheme}
                  className="flex items-center gap-2 text-sm font-medium hover:text-white transition-colors bg-slate-900 px-3 py-2 rounded-lg border border-slate-800 hover:border-slate-700"
                  aria-label={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode from footer`}
               >
                  {theme === 'dark' ? <Sun size={16} /> : <Moon size={16} />}
                  <span>{theme === 'dark' ? 'Light Mode' : 'Dark Mode'}</span>
               </button>
            </div>
          </div>

          <div>
            <h4 className="text-white font-bold mb-6">Company</h4>
            <nav aria-label="Footer company links">
              <ul className="space-y-4">
                {NAV_ITEMS.map((item) => (
                  <li key={item.label}>
                    <a href={item.href} onClick={(e) => handleNavClick(e, item.href)} aria-label={`Navigate to ${item.label} section`} className="hover:text-blue-500 transition-colors text-slate-400 hover:text-blue-400">{item.label}</a>
                  </li>
                ))}
              </ul>
            </nav>
          </div>

          <div>
            <h4 className="text-white font-bold mb-6">Services</h4>
            <nav aria-label="Footer services links">
              <ul className="space-y-4">
                {SERVICES.map((service) => (
